import { execFile, spawn } from "node:child_process";
import fs from "node:fs";
import { promisify } from "node:util";
import { listOrphanWorkdirs, prepareIntegrationWorkdir, prepareWorkdir, reapTaskWorkdirIfTerminal, removeIntegrationWorkdir, runGit, syncTaskDocs, touchWorkdir } from "./project.js";
import { RunnerGitError } from "./project.js";
import { runHarnessStage } from "./harness.js";
import { commitAndPush } from "./gitOps.js";

export const RUNNER_VERSION = "0.1.0";

/***
 * MARK: RUNNER_API_VERSION
 * @description Backend API version this Runner speaks, loaded from
 *   runner/version.json at startup (kept beside daemon.js in the bundle).
 *   Falls back to the pinned fallback when the file is unreadable; the test
 *   suite pins the fallback to runner/version.json.
 * @example RUNNER_API_VERSION => '1.0.0'
 ***/
export const RUNNER_API_VERSION = (() => {
	try {
		const file = new URL("./version.json", import.meta.url);
		const parsed = JSON.parse(fs.readFileSync(file, "utf8"));
		return typeof parsed?.apiVersion === "string" && parsed.apiVersion ? parsed.apiVersion : "1.0.0";
	} catch {
		return "1.0.0";
	}
})();

// Claim renewal cadence: comfortably inside the 5-minute production lease
// TTL (KAINBAIN_CLAIM_TTL_MS) so long harness runs keep their fence. A
// shorter operator TTL still heals via lazy expiry + STALE_EPOCH fencing.
export const CLAIM_HEARTBEAT_MS = 60_000;

const execFileAsync = promisify(execFile);

/***
 * MARK: HARNESS_VERSION_BINS
 * @description CLI binaries probed for `--version` per harness id (G5:
 *   R07/R11 version drift). First binary that answers wins; `mock` has no
 *   CLI and reports a fixed marker. Probing is best-effort with a short
 *   timeout — a missing CLI resolves to "unknown", never a boot failure.
 * @example HARNESS_VERSION_BINS.vibe => ['vibe']
 ***/
export const HARNESS_VERSION_BINS = {
	mock: [],
	pi: ["pi"],
	muse: ["muse"],
	antigravity: ["agy", "antigravity"],
	vibe: ["vibe"],
};

const harnessVersionCache = new Map();

/***
 * MARK: probeHarnessVersions
 * @description Probes the harness CLI's `--version` once per process and
 *   caches it (G5). Returns `{ [harnessId]: version }` for `factsFor`, so
 *   the backend capability record names the real CLI drift instead of
 *   "unknown". Unknown ids and missing/slow CLIs resolve to "unknown".
 * @example await probeHarnessVersions('mock') => { mock: 'mock' }
 * @param {string} harnessId - Harness id (mock, pi, muse, antigravity, vibe).
 * @param {Object} [opts] - Options.
 * @param {number} [opts.timeoutMs=4000] - Per-binary probe timeout.
 * @returns {Promise<Object>} Version map for `factsFor`.
 ***/
export async function probeHarnessVersions(harnessId, { timeoutMs = 4000 } = {}) {
	if (harnessVersionCache.has(harnessId)) return harnessVersionCache.get(harnessId);
	let version = harnessId === "mock" ? "mock" : "unknown";
	for (const bin of HARNESS_VERSION_BINS[harnessId] ?? []) {
		try {
			const res = await execFileAsync(bin, ["--version"], { timeout: timeoutMs });
			const text = typeof res === "string" ? res : (res?.stdout ?? "");
			const first = String(text).split("\n")[0].trim();
			if (first) {
				version = first.slice(0, 120);
				break;
			}
		} catch {
			// Try the next binary; a missing CLI is "unknown", not fatal.
		}
	}
	const versions = { [harnessId]: version };
	harnessVersionCache.set(harnessId, versions);
	return versions;
}

/***
 * MARK: clearHarnessVersionCache
 * @description Test hook: drops the cached `--version` probes so each test
 *   observes a fresh probe.
 * @example clearHarnessVersionCache()
 ***/
export function clearHarnessVersionCache() {
	harnessVersionCache.clear();
}

/***
 * MARK: runnerHarnessIds
 * @description Normalized harness list for one Runner: the csv
 *   `harnessIds` when configured, else the singular primary `harnessId`.
 *   Tolerates hand-built configs (tests) that only set `harnessId`.
 * @example runnerHarnessIds({ harnessId: 'pi' }) => ['pi']
 * @param {Object} [config] - Normalized runner config.
 * @returns {string[]} Harness ids, primary first.
 ***/
export function runnerHarnessIds(config = {}) {
	const ids = Array.isArray(config.harnessIds)
		? config.harnessIds.map((h) => String(h ?? "").trim()).filter(Boolean)
		: [];
	if (ids.length > 0) return ids;
	const primary = String(config.harnessId ?? "").trim();
	return primary ? [primary] : [];
}

/***
 * MARK: applyBackendPrompt
 * @description Retargets a backend-curated prompt to the prepared worktree:
 *   the backend curates with its own project cwd (it owns task/stage truth),
 *   so every occurrence of that cwd prefix is rewritten to the worktree the
 *   harness will actually run in. Empty prompt (old backend) stays empty so
 *   the caller falls back to its minimal prompt.
 * @example applyBackendPrompt({ prompt: 'see /repo/docs', backendCwd: '/repo', workdir: '/w' }) => 'see /w/docs'
 * @param {Object} opts - `{ prompt, backendCwd, workdir }`.
 * @returns {string} The retargeted prompt.
 ***/
export function applyBackendPrompt({ prompt, backendCwd, workdir } = {}) {
	const text = typeof prompt === "string" ? prompt : "";
	if (!text || !backendCwd || !workdir || backendCwd === workdir) return text;
	return text.split(backendCwd).join(workdir);
}

/***
 * MARK: startClaimRenewal
 * @description Renews the task claim on a cadence while a harness runs
 *   (D1): agent stages routinely outlive the claim TTL, and without
 *   renewal the hold lapses mid-stage — the task re-queues, the UI
 *   assignment vanishes, and the finisher reports STALE_EPOCH. Renewal
 *   is best-effort (a failure warns, the final complete surfaces
 *   staleness) and the timer is unref'd so it dies with the daemon —
 *   a dead Runner's hold still lapses.
 * @example const stop = startClaimRenewal({ client, logger, taskId: 't1', ... }); stop();
 * @param {Object} opts - Options (client, logger, taskId, projectId, executionId, epoch, intervalMs?).
 * @returns {Function} Call to stop the renewal timer.
 ***/
export function startClaimRenewal({
	client,
	logger,
	taskId,
	projectId,
	executionId,
	epoch,
	intervalMs = CLAIM_HEARTBEAT_MS,
	onTick = null,
}) {
	const fireTick = () => {
		try {
			if (typeof onTick === "function") onTick();
		} catch {
			// Liveness marking must never break lease renewal.
		}
	};
	const timer = setInterval(() => {
		client
			.claimHeartbeat({ taskId, projectId, executionId, epoch })
			.then(
				() => fireTick(),
				(err) => {
				logger.warn(`Claim renewal failed: ${err?.message || err}`);
				// The backend timed the stage out and released the hold:
				// stop propping it up. The harness run itself continues to
				// its natural finish, whose complete is then stale-rejected
				// by the lease fence — never reported as fresh work.
				if (err?.code === "STAGE_TIMEOUT") clearInterval(timer);
			});
	}, intervalMs);
	if (typeof timer.unref === "function") timer.unref();
	return () => clearInterval(timer);
}

/***
 * MARK: diskHeadroomMbFor
 * @description Measures free space on the filesystem holding the Runner
 *   work root (G4: R10 dispatch cut-off). Synchronous — one statfs call
 *   per heartbeat. Returns null when unmeasurable so the backend
 *   `DISK_LOW` check stays skipped rather than firing on bad data.
 * @example diskHeadroomMbFor('/tmp') => 12345
 * @param {string} workRoot - Runner work root (or any path on that fs).
 * @returns {number|null} Free megabytes, or null when unmeasurable.
 ***/
export function diskHeadroomMbFor(workRoot) {
	for (const candidate of [workRoot, process.cwd()]) {
		try {
			if (!candidate) continue;
			const st = fs.statfsSync(candidate);
			if (st && Number.isFinite(st.bavail) && Number.isFinite(st.bsize)) {
				return Math.floor((st.bavail * st.bsize) / (1024 * 1024));
			}
		} catch {
			// Try the next candidate; unmeasurable stays null.
		}
	}
	return null;
}

/***
 * MARK: defaultLoadHarness
 * @description Resolves a harness implementation by id for loopback runs.
 *   Anything HarnessSession-conforming works; only the ids below are
 *   wired (anything else fails fast naming what is supported).
 * @example const h = await defaultLoadHarness('mock')
 * @param {string} harnessId - Harness id (mock, pi, muse, antigravity, vibe).
 * @returns {Promise<Object>} Harness with `createSession`.
 ***/
export async function defaultLoadHarness(harnessId) {
	if (harnessId === "mock") {
		const { createMockHarness } = await import(
			"../api/agent/harnesses/mock/mockHarness.js"
		);
		return createMockHarness({ models: [] });
	}
	if (harnessId === "pi") {
		const { createPiHarness } = await import("../api/agent/harnesses/pi/piHarness.js");
		return createPiHarness({});
	}
	if (harnessId === "muse") {
		const { createMuseHarness } = await import(
			"../api/agent/harnesses/muse/museHarness.js"
		);
		return createMuseHarness({});
	}
	if (harnessId === "antigravity") {
		const { createAntigravityHarness } = await import(
			"../api/agent/harnesses/antigravity/agyHarness.js"
		);
		return createAntigravityHarness({});
	}
	if (harnessId === "vibe") {
		const { createVibeHarness } = await import(
			"../api/agent/harnesses/vibe/vibeHarness.js"
		);
		return createVibeHarness({});
	}
	throw new Error(`Unknown harness ${harnessId} (supported: mock, pi, muse, antigravity, vibe).`);
}

function factsFor({ config, harnessVersions }) {
	const versionFor = (id) =>
		harnessVersions?.[id] ?? harnessVersionCache.get(id)?.[id] ?? "unknown";
	return {
		harnesses: runnerHarnessIds(config).map((id) => ({ id, version: versionFor(id) })),
		models:
			Array.isArray(config.models) && config.models.length > 0
				? [...config.models]
				: config.model
					? [config.model]
					: [],
		tiers: config.tiers,
		diskHeadroomMb: diskHeadroomMbFor(config.workRoot),
		versions: { protocol: "v1", runner: RUNNER_VERSION, api: RUNNER_API_VERSION },
	};
}

/***
 * MARK: joinAndHeartbeat
 * @description Shared join prologue: poll a pending join until the human
 *   approves (then exit asking for the pasted credential), load the
 *   harness, heartbeat once, and start the background heartbeat timer.
 * @example const { harness, stop } = await joinAndHeartbeat({ config, client, loadHarness, logger, state })
 * @param {Object} opts - Options.
 * @param {Object} opts.config - Normalized runner config.
 * @param {Object} opts.client - Runner backend client.
 * @param {Function} opts.loadHarness - Harness loader.
 * @param {Object} opts.logger - Logger.
 * @param {Object} opts.state - Live-execution ref (`{ session, executionId, epoch }`), read by the steer pull cycle.
 * @returns {Promise<Object>} Primary `harness`, full `harnesses` map, plus `stop()` for the timer.
 ***/
async function joinAndHeartbeat({ config, client, loadHarness, logger, state }) {
	if (!config.credential) {
		if (!config.joinToken) {
			throw new Error("No credential and no KAINBAIN_RUNNER_JOIN_TOKEN: cannot join.");
		}
		const deadline = Date.now() + config.approvalTimeoutMs;
		// Probe before the first register so even a pending join advertises
		// the real harness CLI versions (G5).
		const joinVersions = {};
		for (const id of runnerHarnessIds(config)) {
			Object.assign(joinVersions, await probeHarnessVersions(id));
		}
		for (;;) {
			const reg = await client.register({
				runnerId: config.runnerId,
				joinToken: config.joinToken,
				facts: factsFor({ config, harnessVersions: joinVersions }),
			});
			if (reg.status === "active") break;
			if (Date.now() > deadline) {
				throw new Error(`Join for ${config.runnerId} still ${reg.status} after timeout.`);
			}
			logger.log(`Join ${reg.status}; waiting for human approval in Settings › Harness › Runners…`);
			await new Promise((r) => setTimeout(r, config.approvalPollMs));
		}
		throw new Error(
			`Join for ${config.runnerId} approved. Paste the one-time credential shown in Settings › Harness › Runners into KAINBAIN_RUNNER_CREDENTIAL and restart.`,
		);
	}
	client.setCredential(config.credential);

	// Multi-harness service: load every advertised harness once; each
	// dispatch answer then serves with its required one.
	const harnesses = {};
	for (const id of runnerHarnessIds(config)) {
		harnesses[id] = await loadHarness(id);
	}
	const harness = harnesses[config.harnessId] ?? Object.values(harnesses)[0];
	if (!harness) {
		throw new Error("Runner has no harness configured (KAINBAIN_RUNNER_HARNESS or KAINBAIN_RUNNER_HARNESSES).");
	}
	// G5: probe each harness CLI version once at load; every later factsFor
	// call (register, heartbeats, steer pulls) reuses the cached probes, so
	// the backend sees real CLI drift instead of "unknown".
	const harnessVersions = {};
	for (const id of runnerHarnessIds(config)) {
		Object.assign(harnessVersions, await probeHarnessVersions(id));
	}
	const facts = factsFor({ config, harnessVersions });
	const beat = await client.heartbeat({ runnerId: config.runnerId, facts });
	if (beat.status !== "active") {
		throw new Error(`Runner ${config.runnerId} is ${beat.status}; need an active registration.`);
	}
	const heartbeatTimer = setInterval(() => {
		// Fresh facts every beat: disk headroom is re-measured (G4) while
		// the harness CLI version resolves from the load-time probe cache.
		deliverSteers({ config, client, logger, facts: factsFor({ config }), state }).catch((err) => {
			logger.warn(`Heartbeat failed: ${err?.message || err}`);
		});
	}, config.heartbeatMs);
	if (typeof heartbeatTimer.unref === "function") heartbeatTimer.unref();
	return { harness, harnesses, facts, stop: () => clearInterval(heartbeatTimer) };
}

/***
 * MARK: deliverSteers
 * @description One D5 pull cycle (ADR 0011): heartbeat, deliver each
 *   pending steer for the CURRENT execution to the live session
 *   (`steer`, falling back to `followUp`), and ack exactly once. Steers
 *   for any other execution are ignored (stale lease, never ours).
 *   A session without either method NACKs UNSUPPORTED_HARNESS — loud,
 *   never silently dropped.
 * @example await deliverSteers({ config, client, logger, facts, state })
 * @param {Object} opts - Options (config, client, logger, facts, state).
 * @returns {Promise<number>} Steers delivered (acked) this cycle.
 ***/
export async function deliverSteers({ config, client, logger, facts, state }) {
	const beat = await client.heartbeat({ runnerId: config.runnerId, facts });
	const due = (beat.pendingSteers || []).filter((s) => s && s.executionId === state?.executionId);
	let delivered = 0;
	for (const steer of due) {
		const session = state.session;
		let ok = true;
		let detail = "delivered";
		try {
			if (session && typeof session.steer === "function") {
				await session.steer(steer.text);
			} else if (session && typeof session.followUp === "function") {
				await session.followUp(steer.text);
			} else {
				ok = false;
				detail = "UNSUPPORTED_HARNESS";
			}
		} catch (err) {
			ok = false;
			detail = String(err?.message || err).slice(0, 500);
		}
		try {
			await client.steerAck({
				taskId: steer.taskId,
				projectId: steer.projectId,
				executionId: steer.executionId,
				epoch: steer.epoch,
				steerId: steer.steerId,
				ok,
				detail,
			});
			delivered += 1;
		} catch (err) {
			logger.warn(`Steer ack failed: ${err?.message || err}`);
		}
	}
	return delivered;
}

/**
 * MARK: CI_TIMEOUT_EXIT_CODE
 * @description Exit code reported when the CI budget fires (mirrors GNU
 *   timeout's 124), so a timeout is distinguishable from a failing suite.
 * @example CI_TIMEOUT_EXIT_CODE => 124
 **/
export const CI_TIMEOUT_EXIT_CODE = 124;

/***
 * MARK: ciWorkdirFor
 * @description Working directory for a dispatched CI stage: the task
 *   worktree by default, or the primary checkout (project.cwd on this host)
 *   when the stage declares runOnBranch 'primary' — the same contract the
 *   backend's embedded path honours. Post-merge stages (e.g. publish) need
 *   the primary tree, not the task branch.
 * @example ciWorkdirFor({ runOnBranch: 'primary', workdir: '/w/kb-t', projectCwd: '/repo' }) => '/repo'
 * @example ciWorkdirFor({ runOnBranch: 'task', workdir: '/w/kb-t', projectCwd: '/repo' }) => '/w/kb-t'
 * @param {Object} opts - `{ runOnBranch, workdir, projectCwd }`.
 * @returns {string} Directory the CI command runs in.
 ***/
export function ciWorkdirFor({ runOnBranch, workdir, projectCwd } = {}) {
	if (
		typeof runOnBranch === "string" &&
		runOnBranch.trim().toLowerCase() === "primary" &&
		typeof projectCwd === "string" &&
		projectCwd
	) {
		return projectCwd;
	}
	return workdir;
}

/***
 * MARK: runCiCommand
 * @description Runs one backend-dispatched CI/command stage in the worktree:
 *   shell command (already keyword-expanded by the backend, backend cwd
 *   retargeted to the worktree), output streamed to onLog and collected
 *   (tail-capped). Resolves { exitCode, timedOut, timeoutMs, output } —
 *   non-zero is a result, not a throw; spawn failure resolves exitCode 1
 *   with the error as output. The shell leads its own process group so the
 *   timeout kills the whole tree: killing only the shell orphaned the gate
 *   (it ran to green while close() reported signal-death as exit 1, task
 *   b5716327).
 * @example await runCiCommand({ command: 'true', workdir: '/w', onLog: () => {} }) => { exitCode: 0 }
 * @param {Object} opts - `{ command, workdir, timeoutMs?, onLog?, env? }`.
 * @returns {Promise<Object>} `{ exitCode, timedOut, timeoutMs, output }`.
 ***/
export function runCiCommand({ command, workdir, timeoutMs = 600000, onLog = () => {}, env = {} } = {}) {
	return new Promise((resolve) => {
		const shell = process.platform === "win32" ? "cmd" : "/bin/bash";
		const args = process.platform === "win32" ? ["/c", command] : ["-c", command];
		const effectiveTimeoutMs = timeoutMs > 0 ? timeoutMs : 600000;
		let child;
		try {
			child = spawn(shell, args, {
				cwd: workdir,
				env: { ...process.env, ...env },
				detached: process.platform !== "win32",
			});
		}
		catch (err) { resolve({ exitCode: 1, timedOut: false, timeoutMs: effectiveTimeoutMs, output: String(err?.message || err) }); return; }
		let output = "";
		let timedOut = false;
		const timer = setTimeout(() => {
			timedOut = true;
			try {
				if (child.pid !== undefined && process.platform !== "win32") {
					try { process.kill(-child.pid, "SIGKILL"); } catch {}
				}
				try { child.kill("SIGKILL"); } catch {}
			} catch {}
			output = `${output}\nCI command timed out after ${effectiveTimeoutMs}ms\n`;
		}, effectiveTimeoutMs);
		const onData = (buf) => { const text = buf.toString(); output = (output + text).slice(-20000); try { onLog(text); } catch {} };
		child.stdout?.on("data", onData); child.stderr?.on("data", onData);
		child.on("error", (err) => { clearTimeout(timer); resolve({ exitCode: 1, timedOut: false, timeoutMs: effectiveTimeoutMs, output: output + String(err?.message || err) }); });
		child.on("close", (code) => { clearTimeout(timer); resolve({ exitCode: timedOut ? CI_TIMEOUT_EXIT_CODE : (typeof code === "number" ? code : 1), timedOut, timeoutMs: effectiveTimeoutMs, output }); });
	});
}

/***
 * MARK: executeAssignment
 * @description Shared execution body: claim (or consume the dispatch
 *   answer's lease — the route already claim-fenced it), load, run,
 *   commit/push, and complete one assignment (used by both
 *   single-assignment and loop).
 * @example await executeAssignment({ config, client, logger, harness, state, projectId, taskId })
 * @param {Object} opts - Options (config, client, logger, harness, state, projectId, taskId, lease?, model?, harnessId?).
 * @param {string} [opts.model] - Required model from the dispatch answer
 *   (`requirements.model`); the runner serves exactly that, never a
 *   substitution. Falls back to the pinned `config.model` (single-assignment
 *   mode or a model-less task), else the harness default.
 * @param {string} [opts.harnessId] - Serving harness id for the posture
 *   line; defaults to the primary `config.harnessId`.
 * @param {Object} [opts.ciEnv] - Backend-curated extra environment for a
 *   dispatched CI command (opaque string bag, e.g. continuity markers the
 *   command needs to recognise a re-dispatch). Sanitized and merged under
 *   the daemon-owned identity keys, which always win.
 * @returns {Promise<Object>} Execution summary.
 ***/

/***
 * MARK: sanitizeCiEnv
 * @description Bounds an assignment-provided env bag to a flat map of
 *   non-empty string keys to non-empty string values (at most 100 entries,
 *   mirroring the backend lifecycle seam): the dispatch payload is
 *   backend-curated, but the child environment must stay a string map.
 *   Non-objects read as empty so a missing/foreign `env` degrades to
 *   today's behaviour. Total on untrusted input.
 * @example sanitizeCiEnv({ A: '1', B: 2 }) => { A: '1' }
 * @param {unknown} value - Candidate env bag from the dispatch answer/claim.
 * @returns {Object} Sanitized string map (possibly empty).
 ***/
export function sanitizeCiEnv(value) {
	try {
		if (!value || typeof value !== "object" || Array.isArray(value)) return {};
		const out = {};
		let count = 0;
		for (const [key, val] of Object.entries(value)) {
			if (count >= 100) break;
			if (typeof key !== "string" || !key) continue;
			if (typeof val !== "string" || !val) continue;
			out[key] = val;
			count += 1;
		}
		return out;
	} catch {
		return {};
	}
}
export function collectTaskFiles({ workdir, taskId } = {}) {
	const dir = `${workdir}/docs/tasks/${taskId}`;
	const files = [];
	let total = 0;
	try {
		for (const name of fs.readdirSync(dir)) {
			if (name === "task.md") continue;
			try {
				const content = fs.readFileSync(`${dir}/${name}`, "utf8");
				const bytes = Buffer.byteLength(content, "utf8");
				if (bytes > 256 * 1024 || total + bytes > 1024 * 1024) continue;
				files.push({ name, content });
				total += bytes;
			} catch { /* unreadable/binary: skip */ }
		}
	} catch { /* no task docs: nothing to ship */ }
	return files;
}

async function executeAssignment({
	config,
	client,
	logger,
	harness,
	state,
	projectId,
	taskId,
	lease,
	backendPrompt = "",
	kind = "",
	ciCommand = "",
	ciTimeoutMs = 0,
	ciEnv = null,
	model = null,
	harnessId = null,
	runOnBranch = "",
	integration = null,
}) {
	const servingHarnessId = harnessId || config.harnessId || "unknown";
		const project = await client.getProject(projectId);
		const task = await client.getTask(projectId, taskId);
		const stageId = String(task.currentStageId ?? task.stages?.[0]?.id ?? "stage");

		const runStartedAt = Date.now();
		// Dispatch already holds the lease (scan → match → claim-fence);
		// re-claiming it would 409 against ourselves. Single-assignment
		// has no lease yet, so it claims here.
		const claim = lease ?? (await client.claim({ taskId, projectId }));
		const { executionId, epoch } = claim;
		if (!backendPrompt && typeof claim.prompt === "string") backendPrompt = claim.prompt;
		if (!kind && typeof claim.kind === "string") kind = claim.kind;
		if (!ciCommand && typeof claim.command === "string") ciCommand = claim.command;
		if (!ciTimeoutMs && Number(claim.timeoutMs)) ciTimeoutMs = Number(claim.timeoutMs);
		if (!runOnBranch && typeof claim.runOnBranch === "string") runOnBranch = claim.runOnBranch;
		if (ciEnv === null || ciEnv === undefined) ciEnv = claim.env;
		if (integration === null || integration === undefined) integration = claim.integration ?? null;
		// Leased integrations run their own procedure (Step 4): ephemeral
		// worktree, merge, CAS-push, verify — no harness, no task worktree.
		if (kind === "integrate") {
			return executeIntegrationAssignment({
				config, client, logger, state, projectId, taskId, claim, integration: integration || {},
			});
		}
		// Publish the live execution for the steer pull cycle (D5); the
		// heartbeat loop only ever delivers steers for THIS execution.
		state.executionId = executionId;
		state.epoch = epoch;
		state.session = null;
		// Lease renewal (D1): agent stages routinely outlive the claim
		// TTL, so extend the hold while the harness runs (see
		// startClaimRenewal).
		const stopRenewal = startClaimRenewal({
			client,
			logger,
			taskId,
			projectId,
			executionId,
			epoch,
			// Keep this workdir fresh for LRU eviction: a live run must never
			// look stale to a sibling Runner's cap relief.
			onTick: () => {
				if (state.workdir) touchWorkdir(state.workdir);
			},
		});
		try {
			await client.progress({
				taskId: taskId,
				projectId: projectId,
				executionId,
				epoch,
				stageId,
				event: "started",
			});
			const { workdir, branch, mode, reused, recoveredTo, baseSha, evicted } = await prepareWorkdir({
				repoUrl: project.gitUrl || project.repoUrl || null,
				localPath: project.cwd || null,
				workRoot: config.workRoot,
				taskId: taskId,
			});
			state.workdir = workdir;
			logger.log(`Workdir ${workdir} (${mode}${reused ? ", reused" : ""}${baseSha ? `, base ${baseSha.slice(0, 7)}` : ""}${recoveredTo ? `, residue parked on ${recoveredTo}` : ""}${evicted ? `, evicted stale ${evicted.evicted}${evicted.parkedTo ? ` (residue parked on ${evicted.parkedTo})` : ""}` : ""}).`);
			// Task prompt inputs (idea files, reference images) land in the
			// live task folder outside the task branch — mirror them into
			// the worktree so the harness actually sees them.
			try {
				const synced = await syncTaskDocs({ primaryCwd: project.cwd || null, workdir, taskId });
				if (synced > 0) logger.log(`Synced ${synced} task-doc file(s) into worktree.`);
			} catch (err) {
				logger.log(`Task-doc sync skipped: ${err?.message || err}`);
			}

			let seq = 0;
			const sendLogs = async (bytes) => {
				for (const chunk of String(bytes).split("\n")) {
					if (!chunk) continue;
					await client.logs({
						taskId: taskId,
						projectId: projectId,
						executionId,
						epoch,
						seq: seq++,
						bytes: chunk.slice(0, 4000),
					});
				}
			};

			// Backend-curated stage prompt (backend owns curation; the
			// Runner only retargets the backend cwd prefix to the worktree).
			// Absent prompt (old backend) falls back to the minimal prompt.
			let prompt = applyBackendPrompt({ prompt: backendPrompt, backendCwd: project.cwd, workdir });
			if (!prompt) {
				prompt = [`Task goal: ${task.goal || task.title || taskId}`, `Stage: ${stageId}`].join("\n");
			}
			prompt = [
				prompt,
				`Working directory: ${workdir}`,
				`Branch: ${branch}`,
				"Implement the stage goal in the working directory. Keep changes scoped to the task.",
			].join("\n");

			// Report the exact stage prompt plus the serving harness/model
			// for the monitor's with-prompt cards. Best-effort and
			// observability-only: a failed report must never fail the
			// stage itself.
			try {
				await client.progress({
					taskId: taskId,
					projectId: projectId,
					executionId,
					epoch,
					stageId,
					event: "prompted",
					prompt,
					harness: servingHarnessId,
					model: config.model || "default",
				});
			} catch (err) {
				logger.warn(`Prompt report failed: ${err?.message || err}`);
			}

			if (kind === "ci") {
				const ciWorkdir = ciWorkdirFor({ runOnBranch, workdir, projectCwd: project.cwd });
				const command = applyBackendPrompt({ prompt: ciCommand, backendCwd: project.cwd, workdir: ciWorkdir });
				logger.log(`CI stage command: ${command} (cwd ${ciWorkdir})`);
				// Backend-curated assignment env (continuity markers et al.)
				// flows to the child under the daemon-owned identity keys,
				// which always win so an assignment can never spoof them.
				const ci = await runCiCommand({
					command, workdir: ciWorkdir,
					timeoutMs: ciTimeoutMs || 600000,
					env: { ...sanitizeCiEnv(ciEnv), KAINBAIN_TASK_ID: taskId, KAINBAIN_TASK_DOCS: `${workdir}/docs/tasks/${taskId}` },
					onLog: (text) => { sendLogs(text).catch(() => {}); },
				});
				state.session = null; stopRenewal();
				await client.progress({ taskId, projectId, executionId, epoch, stageId, event: "finished" });
				const sha = (await runGit(ciWorkdir, ["rev-parse", "HEAD"])).stdout.trim();
				if (ci.exitCode !== 0) {
					const failureReason = ci.timedOut
						? `CI command timed out after ${ci.timeoutMs}ms`
						: `CI command failed with exit code ${ci.exitCode}`;
					return await client.complete({ taskId, projectId, executionId, epoch, sha, branch, outcome: "failed", failureReason, taskFiles: collectTaskFiles({ workdir, taskId }), output: ci.output.slice(0, 20000), posture: `${config.tiers.join("/")}:${servingHarnessId}:${config.model || "default"}`, durationMs: Date.now() - runStartedAt });
				}
				return await client.complete({ taskId, projectId, executionId, epoch, sha, branch, outcome: "passed", taskFiles: collectTaskFiles({ workdir, taskId }), output: ci.output.slice(0, 20000), posture: `${config.tiers.join("/")}:${servingHarnessId}:${config.model || "default"}`, durationMs: Date.now() - runStartedAt });
			}

			// The backend project record's cwd points at the backend's own
			// checkout — on the Runner host the task's working copy is the
			// prepared worktree. Run the session THERE, or the agent's file
			// writes land in the wrong repo and the commit/push ships
			// nothing (wire-proof 2026-10-27: hello-wire.txt landed in the
			// backend project dir instead of the worktree).
			const { output } = await runHarnessStage({
				harness,
				project: { ...project, cwd: workdir },
				workdir,
				taskId: taskId,
				stageId,
				model: model || config.model,
				prompt,
				onLog: (text) => {
					sendLogs(text).catch((err) => {
						logger.warn(`Log ingest failed: ${err?.message || err}`);
					});
				},
				onSession: (session) => {
					state.session = session;
				},
			});
			state.session = null;
			stopRenewal();
			await client.progress({
				taskId: taskId,
				projectId: projectId,
				executionId,
				epoch,
				stageId,
				event: "finished",
			});

			const { sha, pushed, pushSkipped, beforeSha, pushState } = await commitAndPush({
				workdir,
				branch,
				taskDocsPath: `docs/tasks/${taskId}`,
				message: `kb/${taskId} ${stageId}: Runner ${config.runnerId} stage output`,
				author: `kainbain-runner/${config.runnerId}`,
			});
			logger.log(`Committed ${sha} (pushed: ${pushed}${pushSkipped ? `, ${pushSkipped}` : ""}${pushState && pushState !== "pushed" ? `, ${pushState}` : ""}${beforeSha && beforeSha !== sha ? `, base was ${beforeSha.slice(0, 7)}` : ""}).`);
			if (output) {
				await sendLogs(`stage output: ${String(output).slice(0, 4000)}`);
			}
			return await client.complete({
				taskId: taskId,
				projectId: projectId,
				executionId,
				epoch,
				sha,
				branch,
				posture: `${config.tiers.join("/")}:${servingHarnessId}:${config.model || "default"}`,
				outcome: "passed",
				taskFiles: collectTaskFiles({ workdir, taskId }),
				output: String(output || "").slice(0, 20000),
				durationMs: Date.now() - runStartedAt,
			});
		} catch (err) {
			stopRenewal();
			if (err?.code === "STALE_EPOCH") throw err;
			if (err?.code === "WORKTREE_CAP_REACHED") {
				// Infra exhaustion, not task fault: re-queue via interrupt
				// and keep polling. Throwing here killed the Runner process,
				// and systemd restart storms turned one refusal into a task
				// death loop (e79b1d25). The reason travels on the interrupt
				// so the task history names the cause instead of a bare
				// "lease dropped".
				const reason = `Runner workdir unavailable: ${err.message}`;
				if (typeof logger.error === "function") logger.error(reason);
				else logger.log(reason);
				try {
					await client.interrupt({ taskId, projectId, executionId, reason });
				} catch {
					// Interrupting is best-effort: the lease TTL still bounds the damage.
				}
				return { interrupted: true, executionId, epoch, reason };
			}
			if (err?.failedOutcome) {
				// The harness ran and failed: report through the engine's
				// failure routing (verdict/failback) instead of parking.
				return await client.complete({
					taskId: taskId,
					projectId: projectId,
					executionId,
					epoch,
					outcome: "failed",
					failureReason: err.failedOutcome,
					posture: `${config.tiers.join("/")}:${servingHarnessId}:${config.model || "default"}`,
					durationMs: Date.now() - runStartedAt,
				});
			}
			try {
				await client.interrupt({
					taskId: taskId,
					projectId: projectId,
					executionId,
				});
			} catch {
				// Interrupting is best-effort: the lease TTL still bounds the damage.
			}
			throw err;
		}
}

/***
 * MARK: executeIntegrationAssignment
 * @description Runs one leased `integrate` job (Step 4): merges
 *   `origin/<taskBranch>` into the target in an ephemeral detached worktree,
 *   CAS-pushes the target against the expected SHA, re-verifies, and reports.
 *   The task claim fences progress/logs/completion exactly like any stage;
 *   the integration lease serializes target writes. Outcomes:
 *   `landed` (merge pushed + verified → task completes passed with the
 *   integration payload the backend finalize needs), `conflict` (structured
 *   file list — never resolved here — task fails back visibly), or
 *   `stale-head` (a ref moved mid-lease → task fails with a retryable
 *   reason; the retry re-bases with fresh SHAs). The ephemeral worktree is
 *   removed in all outcomes.
 * @example await executeIntegrationAssignment({ config, client, logger, state, projectId: 'p', taskId: 't', claim, integration }) => { ... }
 ***/
async function executeIntegrationAssignment({
	config,
	client,
	logger,
	state,
	projectId,
	taskId,
	claim,
	integration,
}) {
	const { taskBranch, expectedTaskSha, targetBranch, expectedTargetSha, mergeAttemptId } = integration;
	const integrationExecutionId = integration.integrationExecutionId;
	const integrationEpoch = integration.integrationEpoch;
	const runStartedAt = Date.now();
	const project = await client.getProject(projectId);
	const task = await client.getTask(projectId, taskId);
	const stageId = String(task.currentStageId ?? task.stages?.[0]?.id ?? "stage");
	const { executionId, epoch } = claim;
	state.executionId = executionId;
	state.epoch = epoch;
	state.session = null;
	const posture = `${(config.tiers || []).join("/")}:integration:${config.model || "default"}`;
	const stopRenewal = startClaimRenewal({ client, logger, taskId, projectId, executionId, epoch });
	const integrationTimer = setInterval(() => {
		client
			.integrationHeartbeat({ projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch })
			.catch((err) => {
				logger.warn(`Integration renewal failed: ${err?.message || err}`);
				if (err?.code === "STALE_EPOCH") clearInterval(integrationTimer);
			});
	}, CLAIM_HEARTBEAT_MS);
	if (typeof integrationTimer.unref === "function") integrationTimer.unref();

	let seq = 0;
	const sendLogs = async (bytes) => {
		for (const chunk of String(bytes).split("\n")) {
			if (!chunk) continue;
			await client.logs({ taskId, projectId, executionId, epoch, seq: seq++, bytes: chunk.slice(0, 4000) });
		}
	};
	const finishProgress = () =>
		client.progress({ taskId, projectId, executionId, epoch, stageId, event: "finished" }).catch(() => {});
	const failTask = (failureReason, extra = {}) =>
		client.complete({
			taskId, projectId, executionId, epoch,
			branch: taskBranch, outcome: "failed", failureReason,
			posture, durationMs: Date.now() - runStartedAt, ...extra,
		});

	try {
		await client.progress({ taskId, projectId, executionId, epoch, stageId, event: "started" });
		const { workdir, mirrorDir } = await prepareIntegrationWorkdir({
			repoUrl: project.gitUrl || project.repoUrl || null,
			workRoot: config.workRoot,
			taskBranch,
			expectedTaskSha,
			targetBranch,
			expectedTargetSha,
		});
		logger.log(`Integration workdir ${workdir} (ephemeral, detached at ${String(expectedTargetSha).slice(0, 7)}).`);
		try {
			try {
				await sendLogs(`[integrate] merging origin/${taskBranch} into ${targetBranch}`);
				await runGit(workdir, [
					"-c", "user.name=KainBain Integration",
					"-c", "user.email=kainbain-runner@local",
					"merge", "--no-edit", `origin/${taskBranch}`,
				]);
			} catch (mergeErr) {
				let conflicted = [];
				try {
					const { stdout } = await runGit(workdir, ["diff", "--name-only", "--diff-filter=U"]);
					conflicted = stdout.split("\n").map((l) => l.trim()).filter(Boolean);
				} catch {
					// Best effort: the file list below degrades to unknown.
				}
				try {
					await runGit(workdir, ["merge", "--abort"]);
				} catch {
					// Best effort: the tree may already be clean.
				}
				const looksLikeConflict =
					conflicted.length > 0 ||
					/CONFLICT|Automatic merge failed|unmerged/i.test(`${mergeErr?.message || ""}\n${mergeErr?.stderr || ""}`);
				if (!looksLikeConflict) throw mergeErr;
				const detail = `Merge conflicts in: ${conflicted.join(", ") || "unknown files"} — resolve on '${taskBranch}' and retry the merge stage`;
				await sendLogs(`[integrate] conflict: ${detail}`);
				await client.integrationReport({
					projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch,
					outcome: "conflict", detail,
				}).catch(() => {});
				state.session = null; stopRenewal(); clearInterval(integrationTimer);
				await finishProgress();
				return await failTask(detail, { taskFiles: collectTaskFiles({ workdir, taskId }) });
			}
			const mergeSha = (await runGit(workdir, ["rev-parse", "HEAD"])).stdout.trim();
			try {
				await runGit(workdir, [
					"push", `--force-with-lease=${targetBranch}:${expectedTargetSha}`,
					"origin", `${mergeSha}:${targetBranch}`,
				]);
			} catch (pushErr) {
				const detail = `Target '${targetBranch}' moved during integration (CAS push pinned at ${String(expectedTargetSha).slice(0, 7)} rejected) — retry re-bases with fresh SHAs`;
				await sendLogs(`[integrate] stale-head: ${detail}`);
				await client.integrationReport({
					projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch,
					outcome: "stale-head", detail,
				}).catch(() => {});
				state.session = null; stopRenewal(); clearInterval(integrationTimer);
				await finishProgress();
				return await failTask(detail);
			}
			await runGit(mirrorDir, ["fetch", "origin"]);
			const tip = (await runGit(mirrorDir, ["rev-parse", "--verify", `origin/${targetBranch}`])).stdout.trim();
			let ancestry = false;
			try {
				await runGit(mirrorDir, ["merge-base", "--is-ancestor", mergeSha, tip]);
				ancestry = true;
			} catch {
				ancestry = false;
			}
			await client.integrationReport({
				projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch,
				outcome: "landed", mergeSha, detail: `merged '${taskBranch}' into '${targetBranch}'`,
			});
			state.session = null; stopRenewal(); clearInterval(integrationTimer);
			await finishProgress();
			if (ancestry) {
				await client.verifySha({ taskId, projectId, executionId, epoch, sha: mergeSha, present: true }).catch(() => {});
			}
			return await client.complete({
				taskId, projectId, executionId, epoch,
				sha: mergeSha, branch: taskBranch, outcome: "passed",
				posture, durationMs: Date.now() - runStartedAt,
				output: `[integrate] merged '${taskBranch}' into '${targetBranch}' (${mergeSha.slice(0, 7)})`,
				integration: {
					outcome: "landed", mergeSha, taskBranch, expectedTaskSha,
					targetBranch, expectedTargetSha, mergeAttemptId,
				},
			});
		} finally {
			await removeIntegrationWorkdir(mirrorDir, workdir);
		}
	} catch (err) {
		stopRenewal();
		clearInterval(integrationTimer);
		if (err?.code === "STALE_EPOCH") throw err;
		if (err instanceof RunnerGitError && err.code === "stale-head") {
			await client.integrationReport({
				projectId, targetBranch, executionId: integrationExecutionId, epoch: integrationEpoch,
				outcome: "stale-head", detail: err.message,
			}).catch(() => {});
			await finishProgress();
			return await failTask(`stale-head: ${err.message}`);
		}
		try {
			await client.interrupt({ taskId, projectId, executionId });
		} catch {
			// Interrupting is best-effort: the lease TTL still bounds the damage.
		}
		throw err;
	}
}

/***
 * MARK: runSingleAssignment
 * @description One explicit task assignment over the wire (ADR 0009 steps
 *   1–6, loopback): register (or poll a pending join until the human
 *   approves, then exit asking for the pasted credential), heartbeat,
 *   claim, load (clone/pull or adopt + per-task worktree), run the stage
 *   through the harness, stream sequenced logs, commit/push (push skipped
 *   `no-remote`), and complete with the SHA. Any failure after the claim
 *   interrupts the task so it re-queues as interrupted, never
 *   failed/complete. Orphaned workdirs are surfaced at boot (never deleted
 *   there); past the worktree cap the least-recently-used stale workdir is
 *   evicted on demand, and terminal tasks have their workdir reaped after
 *   the execution reports. Unpushed residue is always parked on
 *   kb-recovery/* first, never deleted.
 * @example await runSingleAssignment({ config, client, loadHarness }) => { executionId, epoch, sha }
 * @param {Object} opts - Options.
 * @param {Object} opts.config - Normalized runner config.
 * @param {Object} opts.client - Runner backend client.
 * @param {Function} [opts.loadHarness] - Harness loader (tests inject fakes).
 * @param {Object} [opts.logger] - Logger (defaults to console).
 * @returns {Promise<Object>} Execution summary.
 ***/
export async function runSingleAssignment({
	config,
	client,
	loadHarness = defaultLoadHarness,
	logger = console,
}) {
	if (config.errors?.length) {
		throw new Error(`Invalid Runner config: ${config.errors.join(" ")}`);
	}
	const orphans = listOrphanWorkdirs(config.workRoot, config.taskId);
	if (orphans.length) {
		logger.warn(`Orphaned workdirs (left alone, may hold unpushed work): ${orphans.join(", ")}`);
	}

	const state = { session: null, executionId: null, epoch: null };
	const { harness, stop } = await joinAndHeartbeat({ config, client, loadHarness, logger, state });
	try {
		const result = await executeAssignment({
			config,
			client,
			logger,
			harness,
			harnessId: config.harnessId,
			state,
			projectId: config.projectId,
			taskId: config.taskId,
		});
		// Terminal tasks never run again: reclaim their workdir slot now
		// instead of growing into the cap (best-effort, never throws).
		await reapTaskWorkdirIfTerminal({
			client,
			projectId: config.projectId,
			taskId: config.taskId,
			workRoot: config.workRoot,
		});
		return result;
	} finally {
		stop();
	}
}

/***
 * MARK: runDispatchLoop
 * @description Capability-aware dispatch loop (WP-3.1): joins and heartbeats
 *   exactly like a single assignment, then polls `POST /runners/dispatch`
 *   for backend-routed work until `dispatchIdleLimit` consecutive polls come
 *   back empty (`dispatchIdleLimit: 0` never idles out — the persistent
 *   service mode). Every poll is server-side scan → match → claim-fence, so
 *   concurrent loops never double-dispatch: a lost race surfaces as
 *   `CLAIM_CONFLICT` inside the fence and the loop simply polls again. A
 *   `STALE_RUNNER` answer triggers one fresh heartbeat and a single retry;
 *   `RUNNER_PAUSED` (operator-parked) backs off and re-polls until resumed;
 *   anything else throws loud.
 * @example await runDispatchLoop({ config, client }) => { assignments: 2, polls: 5 }
 * @param {Object} opts - Options.
 * @param {Object} opts.config - Normalized runner config (dispatch mode).
 * @param {Object} opts.client - Runner backend client.
 * @param {Function} [opts.loadHarness] - Harness loader (tests inject fakes).
 * @param {Object} [opts.logger] - Logger (defaults to console).
 * @returns {Promise<Object>} Loop summary (`assignments`, `polls`).
 ***/
export async function runDispatchLoop({
	config,
	client,
	loadHarness = defaultLoadHarness,
	logger = console,
}) {
	if (config.errors?.length) {
		throw new Error(`Invalid Runner config: ${config.errors.join(" ")}`);
	}
	const orphans = listOrphanWorkdirs(config.workRoot, null);
	if (orphans.length) {
		logger.warn(`Orphaned workdirs (left alone, may hold unpushed work): ${orphans.join(", ")}`);
	}

	const state = { session: null, executionId: null, epoch: null };
	const { harness, harnesses, stop } = await joinAndHeartbeat({ config, client, loadHarness, logger, state });
	const idleLimit = config.dispatchIdleLimit ?? 3;
	const pollMs = config.dispatchPollMs ?? 5000;
	let assignments = 0;
	let polls = 0;
	try {
		for (let idle = 0; ;) {
			let answer;
			try {
				answer = await client.dispatchClaim({ projectIds: config.projectIds ?? null });
			} catch (err) {
				if (err?.code === "STALE_RUNNER") {
					await client.heartbeat({ runnerId: config.runnerId, facts: factsFor({ config }) });
					answer = await client.dispatchClaim({ projectIds: config.projectIds ?? null });
				} else if (err?.statusCode === 429) {
					// D8 backpressure (ADR 0010): the fleet is at its
					// concurrency cap. Back off and re-poll WITHOUT
					// consuming idle budget — work exists, we just
					// may not take it yet.
					polls += 1;
					logger.log(`Dispatch: fleet busy (${err?.code ?? "capped"}); backing off.`);
					await new Promise((r) => setTimeout(r, pollMs));
					continue;
				} else if (err?.code === "RUNNER_PAUSED") {
					// Operator-parked: this Runner takes no new tasks until
					// resumed. Back off and re-poll WITHOUT consuming idle
					// budget — resuming picks the loop straight back up
					// with no restart.
					polls += 1;
					logger.log(`Dispatch: Runner paused by operator; backing off.`);
					await new Promise((r) => setTimeout(r, pollMs));
					continue;
				} else {
					throw err;
				}
			}
			polls += 1;
			if (!answer.assigned) {
				// A busy integration slot is work waiting, not idleness:
				// back off WITHOUT consuming idle budget, like fleet
				// backpressure (D8) and operator pause.
				if (answer.code === "INTEGRATION_BUSY") {
					logger.log(`Dispatch: integration slot busy; backing off.`);
					await new Promise((r) => setTimeout(r, pollMs));
					continue;
				}
				idle += 1;
				// idleLimit 0 means a persistent service loop: never idle out.
				if (idleLimit > 0 && idle >= idleLimit) return { assignments, polls, idle: true };
				logger.log(
					`Dispatch: no work (${answer.code ?? "empty"}); idle ${idle}${idleLimit > 0 ? `/${idleLimit}` : "/∞ (persistent)"}.`,
				);
				await new Promise((r) => setTimeout(r, pollMs));
				continue;
			}
			idle = 0;
			assignments += 1;
			// Multi-harness service: the dispatch answer names the
			// required harness (alias-resolved server-side) — serve with
			// that one, not the primary. An unloaded name falls back to
			// the primary with a warning: the lease is already fenced to
			// us, so stranding it would wedge the task, and the posture
			// line records what actually served.
			const wanted = answer.requirements?.harness || null;
			const servingId =
				wanted && harnesses[wanted] ? wanted : config.harnessId;
			if (wanted && !harnesses[wanted]) {
				logger.warn(
					`Requirements want harness '${wanted}' (not loaded); serving with primary '${servingId}'.`,
				);
			}
			await executeAssignment({
				config,
				client,
				logger,
				harness: harnesses[servingId] ?? harness,
				harnessId: servingId,
				state,
				projectId: answer.projectId,
				taskId: answer.taskId,
				lease: { executionId: answer.executionId, epoch: answer.epoch },
				backendPrompt: answer.prompt || "",
				kind: answer.kind || "",
				ciCommand: answer.command || "",
				runOnBranch: answer.runOnBranch || "",
				ciTimeoutMs: Number(answer.timeoutMs) || 0,
				ciEnv: answer.env,
				// The backend already matched this task against our
				// advertised models: serve exactly its required model.
				model: answer.requirements?.model || null,
				// Leased integrations carry their target/task SHAs here;
				// executeAssignment routes `integrate` to the merge
				// procedure instead of a harness.
				integration: answer.integration ?? null,
			});
			// Terminal tasks never run again: reclaim their workdir slot
			// now instead of growing into the cap (best-effort, never
			// throws).
			await reapTaskWorkdirIfTerminal({
				client,
				projectId: answer.projectId,
				taskId: answer.taskId,
				workRoot: config.workRoot,
			});
		}
	} finally {
		stop();
	}
}

/***
 * MARK: loadRunnerConfig
 * @description Reads Runner daemon configuration from the environment.
 *   The credential is operator-pasted after human approval (D4): when it
 *   is absent the daemon registers, polls until the join is approved, then
 *   exits with instructions instead of running unapproved. Assignment is
 *   explicit (project + task ids) by default; set KAINBAIN_RUNNER_DISPATCH=1
 *   for the capability-aware dispatch loop (WP-3.1), optionally scoped with
 *   KAINBAIN_RUNNER_PROJECTS.
 * @example loadRunnerConfig({ KAINBAIN_RUNNER_ID: 'r1' }) => { runnerId: 'r1', ... }
 * @param {Object} [env] - Environment mapping (defaults to process.env).
 * @returns {Object} Normalized config.
 ***/
export function loadRunnerConfig(env = process.env) {
	const errors = [];
	const str = (key, fallback = "") => {
		const value = env[key] ?? fallback;
		return typeof value === "string" ? value.trim() : String(value ?? "").trim();
	};

	const backendUrl = str("KAINBAIN_RUNNER_BACKEND", "http://localhost:3100").replace(/\/+$/, "");
	const runnerId = str("KAINBAIN_RUNNER_ID", "");
	// Multi-harness service (one Runner, several harnesses): the csv
	// KAINBAIN_RUNNER_HARNESSES wins when set; otherwise the singular
	// KAINBAIN_RUNNER_HARNESS seeds a 1-element list. The first entry
	// stays the primary harness (single-assignment default, posture).
	const harnessIds = str("KAINBAIN_RUNNER_HARNESSES", "")
		.split(",")
		.map((h) => h.trim())
		.filter(Boolean);
	const singularHarness = str("KAINBAIN_RUNNER_HARNESS", "");
	if (harnessIds.length === 0 && singularHarness) harnessIds.push(singularHarness);
	const harnessId = harnessIds[0] ?? "";
	// Servable model advertisement (capability matching is backend-side, so
	// the list is the operator's claim of what this host can run; the
	// dispatch answer carries the required model per assignment and the
	// daemon serves exactly that). KAINBAIN_RUNNER_MODELS (csv) wins when
	// set; otherwise the singular KAINBAIN_RUNNER_MODEL seeds a 1-element
	// list; empty means unpinned (matches model-less tasks only).
	const model = str("KAINBAIN_RUNNER_MODEL", "");
	const models = str("KAINBAIN_RUNNER_MODELS", "")
		.split(",")
		.map((m) => m.trim())
		.filter(Boolean);
	if (models.length === 0 && model) models.push(model);
	const projectId = str("KAINBAIN_RUNNER_PROJECT_ID", "");
	const taskId = str("KAINBAIN_RUNNER_TASK_ID", "");
	if (!runnerId) errors.push("KAINBAIN_RUNNER_ID is required (stable per host).");
	if (!harnessId) errors.push("KAINBAIN_RUNNER_HARNESS is required (e.g. pi, codex, mock).");
	const dispatch = str("KAINBAIN_RUNNER_DISPATCH", "") === "1";
	if (!dispatch && !projectId) {
		errors.push("KAINBAIN_RUNNER_PROJECT_ID is required (or set KAINBAIN_RUNNER_DISPATCH=1).");
	}
	if (!dispatch && !taskId) {
		errors.push("KAINBAIN_RUNNER_TASK_ID is required (or set KAINBAIN_RUNNER_DISPATCH=1).");
	}

	const heartbeatMs = Number.parseInt(str("KAINBAIN_RUNNER_HEARTBEAT_MS", "15000"), 10);
	const approvalPollMs = Number.parseInt(str("KAINBAIN_RUNNER_APPROVAL_POLL_MS", "5000"), 10);
	const approvalTimeoutMs = Number.parseInt(str("KAINBAIN_RUNNER_APPROVAL_TIMEOUT_MS", "300000"), 10);
	const dispatchPollMs = Number.parseInt(str("KAINBAIN_RUNNER_DISPATCH_POLL_MS", "5000"), 10);
	const dispatchIdleLimit = Number.parseInt(str("KAINBAIN_RUNNER_DISPATCH_IDLE_LIMIT", "3"), 10);

	return {
		backendUrl,
		joinToken: str("KAINBAIN_RUNNER_JOIN_TOKEN", ""),
		credential: str("KAINBAIN_RUNNER_CREDENTIAL", ""),
		runnerId,
		harnessId,
		harnessIds,
		model,
		models,
		tiers: str("KAINBAIN_RUNNER_TIERS", "T0,T1")
			.split(",")
			.map((t) => t.trim())
			.filter(Boolean),
		workRoot: str("KAINBAIN_RUNNER_WORK_ROOT", "runner-work"),
		projectId,
		taskId,
		dispatch,
		projectIds: str("KAINBAIN_RUNNER_PROJECTS", "")
			.split(",")
			.map((p) => p.trim())
			.filter(Boolean),
		dispatchPollMs: Number.isFinite(dispatchPollMs) && dispatchPollMs > 0 ? dispatchPollMs : 5000,
		dispatchIdleLimit:
			Number.isFinite(dispatchIdleLimit) && dispatchIdleLimit >= 0 ? dispatchIdleLimit : 3,
		heartbeatMs: Number.isFinite(heartbeatMs) && heartbeatMs > 0 ? heartbeatMs : 15000,
		approvalPollMs: Number.isFinite(approvalPollMs) && approvalPollMs > 0 ? approvalPollMs : 5000,
		approvalTimeoutMs:
			Number.isFinite(approvalTimeoutMs) && approvalTimeoutMs > 0 ? approvalTimeoutMs : 300000,
		errors,
	};
}

/***
 * MARK: createRunnerClient
 * @description Thin fetch wrapper over the Runner-facing backend API
 *   (ADR 0009). Holds the per-Runner credential after approval and sends
 *   it as `x-runner-credential`; every call throws the backend's
 *   `{ error, code }` shape on non-2xx so the daemon can branch on codes.
 * @example const client = createRunnerClient({ backendUrl: 'http://localhost:3100' })
 * @param {Object} opts - Options.
 * @param {string} opts.backendUrl - Backend origin (no trailing slash).
 * @param {Function} [opts.fetchImpl] - Fetch implementation (tests inject a stub).
 * @returns {Object} Runner API client.
 ***/
export function createRunnerClient({ backendUrl, fetchImpl = fetch }) {
	const base = String(backendUrl).replace(/\/+$/, "");
	let credential = "";

	async function call(path, { method = "GET", body, credential: override } = {}) {
		const cred = override ?? credential;
		const res = await fetchImpl(`${base}${path}`, {
			method,
			headers: {
				...(body !== undefined ? { "content-type": "application/json" } : {}),
				...(cred ? { "x-runner-credential": cred } : {}),
			},
			body: body !== undefined ? JSON.stringify(body) : undefined,
		});
		let data = null;
		try {
			data = await res.json();
		} catch {
			data = null;
		}
		if (!res.ok) {
			const err = new Error(data?.error || `Backend ${res.status} on ${path}`);
			err.statusCode = res.status;
			err.code = data?.code ?? null;
			throw err;
		}
		return data;
	}

	return {
		setCredential(next) {
			credential = next;
		},
		register({ runnerId, joinToken, facts }) {
			return call("/runners/register", {
				method: "POST",
				body: { runnerId, joinToken, facts },
			});
		},
		heartbeat({ runnerId, facts }) {
			return call("/runners/heartbeat", {
				method: "POST",
				body: { runnerId, facts },
			});
		},
		claim({ taskId, projectId, runnerId }) {
			return call(`/tasks/${encodeURIComponent(taskId)}/claim`, {
				method: "POST",
				body: { projectId, ...(runnerId ? { runnerId } : {}) },
			});
		},
		claimHeartbeat({ taskId, projectId, executionId, epoch }) {
			return call(`/tasks/${encodeURIComponent(taskId)}/claim-heartbeat`, {
				method: "POST",
				body: { projectId, executionId, epoch },
			});
		},
		dispatchClaim({ projectIds } = {}) {
			return call("/runners/dispatch", {
				method: "POST",
				body: { ...(projectIds?.length ? { projectIds } : {}) },
			});
		},
		integrationHeartbeat({ projectId, targetBranch, executionId, epoch }) {
			return call(`/runners/integration/heartbeat`, {
				method: "POST",
				body: { projectId, targetBranch, executionId, epoch },
			});
		},
		integrationReport({ projectId, targetBranch, executionId, epoch, outcome, mergeSha = null, detail = null }) {
			return call(`/runners/integration/report`, {
				method: "POST",
				body: { projectId, targetBranch, executionId, epoch, outcome, ...(mergeSha ? { mergeSha } : {}), ...(detail ? { detail } : {}) },
			});
		},
		verifySha({ taskId, projectId, executionId, epoch, sha, present }) {
			return call(`/tasks/${encodeURIComponent(taskId)}/verify-sha`, {
				method: "POST",
				body: { projectId, executionId, epoch, sha, present: present !== false },
			});
		},
		steerAck({ taskId, projectId, executionId, epoch, steerId, ok, detail }) {
			return call(`/tasks/${encodeURIComponent(taskId)}/steer-ack`, {
				method: "POST",
				body: {
					projectId,
					executionId,
					epoch,
					steerId,
					ok: ok !== false,
					...(typeof detail === "string" && detail ? { detail: detail.slice(0, 500) } : {}),
				},
			});
		},
		progress({ taskId, projectId, executionId, epoch, stageId, event, prompt = null, harness = null, model = null }) {
			return call(`/tasks/${encodeURIComponent(taskId)}/progress`, {
				method: "POST",
				body: {
					projectId,
					executionId,
					epoch,
					stageId,
					event,
					// Stage prompt payload (observability only, capped like
					// stage output): reported once per assignment so the
					// monitor can show what the Runner was actually told,
					// and on which harness/model it runs.
					...(typeof prompt === "string" && prompt
						? { prompt: prompt.slice(0, 20000) }
						: {}),
					...(typeof harness === "string" && harness ? { harness } : {}),
					...(typeof model === "string" && model ? { model } : {}),
				},
			});
		},
		logs({ taskId, projectId, executionId, epoch, seq, bytes }) {
			return call(`/tasks/${encodeURIComponent(taskId)}/logs`, {
				method: "POST",
				body: { projectId, executionId, epoch, seq, bytes },
			});
		},
		complete({
			taskId,
			projectId,
			executionId,
			epoch,
			sha,
			branch,
			posture,
			outcome,
			output,
			summary,
			modifiedFiles,
			harnessId,
			failureKind,
			failureReason,
			durationMs,
			taskFiles,
		}) {
			return call(`/tasks/${encodeURIComponent(taskId)}/complete-execution`, {
				method: "POST",
				body: {
					projectId,
					executionId,
					epoch,
					...(sha ? { sha } : {}),
					...(branch ? { branch } : {}),
					...(posture ? { posture } : {}),
					...(outcome ? { outcome } : {}),
					...(output ? { output } : {}),
					...(summary ? { summary } : {}),
					...(modifiedFiles ? { modifiedFiles } : {}),
					...(harnessId ? { harnessId } : {}),
					...(failureKind ? { failureKind } : {}),
					...(failureReason ? { failureReason } : {}),
					...(Number.isFinite(durationMs) ? { durationMs } : {}),
				...(Array.isArray(taskFiles) && taskFiles.length ? { taskFiles } : {}),
				},
			});
		},
		interrupt({ taskId, projectId, executionId, reason = null }) {
			return call(`/tasks/${encodeURIComponent(taskId)}/interrupt`, {
				method: "POST",
				body: {
					projectId,
					...(executionId ? { executionId } : {}),
					...(typeof reason === "string" && reason.trim() ? { reason: reason.trim().slice(0, 500) } : {}),
				},
			});
		},
		getProject(projectId) {
			return call(`/projects/${encodeURIComponent(projectId)}`);
		},
		getTask(projectId, taskId) {
			return call(`/tasks/${encodeURIComponent(taskId)}?projectId=${encodeURIComponent(projectId)}`);
		},
		getWorkflow(projectId) {
			return call(`/projects/${encodeURIComponent(projectId)}/workflow`);
		},
	};
}

/***
 * MARK: normalizeCapabilities
 * @description Validates and normalizes a Runner's heartbeat facts into a
 *   capability advertisement struct: harnesses (id + version), models,
 *   tiers, runnable flag, disk headroom, and protocol versions. Unknown
 *   shapes are rejected with an explanatory error list instead of throwing,
 *   so the register/heartbeat routes can answer 400 with all problems.
 * @example normalizeCapabilities({ harnesses: [{ id: 'pi', version: '1.2.3' }], tiers: ['T1'] }) => { harnesses: [...], errors: [] }
 * @param {Object} [facts] - Raw heartbeat facts.
 * @returns {Object} Normalized capabilities plus `errors`.
 ***/
export function normalizeCapabilities(facts = {}) {
	const errors = [];
	const src = facts && typeof facts === "object" ? facts : {};

	const harnesses = [];
	if (src.harnesses !== undefined) {
		if (!Array.isArray(src.harnesses)) {
			errors.push("harnesses must be an array");
		} else {
			for (const h of src.harnesses) {
				if (!h || typeof h.id !== "string" || !h.id.trim()) {
					errors.push("every harness needs a non-empty string id");
					continue;
				}
				harnesses.push({
					id: h.id.trim(),
					version:
						typeof h.version === "string" && h.version.trim()
							? h.version.trim()
							: "unknown",
				});
			}
		}
	}

	const models = [];
	if (src.models !== undefined) {
		if (!Array.isArray(src.models)) {
			errors.push("models must be an array");
		} else {
			for (const m of src.models) {
				if (typeof m === "string" && m.trim()) models.push(m.trim());
			}
		}
	}

	const tiers = [];
	if (src.tiers !== undefined) {
		if (!Array.isArray(src.tiers)) {
			errors.push("tiers must be an array");
		} else {
			for (const t of src.tiers) {
				if (typeof t === "string" && /^T[0-3]$/.test(t.trim())) {
					if (!tiers.includes(t.trim())) tiers.push(t.trim());
				} else {
					errors.push(`unknown tier ${JSON.stringify(t)} (want T0..T3)`);
				}
			}
		}
	}

	let runnable = true;
	if (src.runnable !== undefined) {
		if (typeof src.runnable !== "boolean") {
			errors.push("runnable must be a boolean");
		} else {
			runnable = src.runnable;
		}
	}

	let diskHeadroomMb = null;
	if (src.diskHeadroomMb !== undefined && src.diskHeadroomMb !== null) {
		if (
			typeof src.diskHeadroomMb !== "number" ||
			!Number.isFinite(src.diskHeadroomMb) ||
			src.diskHeadroomMb < 0
		) {
			errors.push("diskHeadroomMb must be a non-negative number");
		} else {
			diskHeadroomMb = src.diskHeadroomMb;
		}
	}

	const versions =
		src.versions && typeof src.versions === "object" ? src.versions : {};

	return { harnesses, models, tiers, runnable, diskHeadroomMb, versions, errors };
}

import { RUNNER_PROTOCOL } from "../runnerRegistry.js";
import { runnerApiCompatible } from "./runnerApiCompat.js";

/***
 * MARK: runnerMatches
 * @description Decides whether one Runner registration can take a task with
 *   the given requirements: active status, not paused, fresh heartbeat
 *   (staleness expiry), v1 protocol, runnable flag, harness id, model
 *   offering, tier membership, and disk headroom floor. Returns
 *   `{ ok, reason }` — the
 *   reason code is loud by design (step-6 NO_CAPABLE_RUNNER diagnostics
 *   and the monitor surface distinguish "no runners" from "runners that
 *   cannot take this job"). Alias requirements always miss here; WP-3.2
 *   resolves them centrally first.
 * @example runnerMatches(record, { harness: 'pi', tier: 'T1' }) => { ok: true, reason: 'MATCH' }
 * @param {Object} record - Registry record (`status`, `facts`, `lastSeenAt`, `capabilities`).
 * @param {Object} req - Task requirements from `taskRequirements`.
 * @param {Object} [opts] - `{ now, staleAfterMs, minDiskHeadroomMb }`.
 * @returns {Object} `{ ok, reason }`.
 ***/
export function runnerMatches(record = {}, req = {}, opts = {}) {
	const now = typeof opts.now === "number" ? opts.now : Date.now();
	const staleAfterMs =
		typeof opts.staleAfterMs === "number" && opts.staleAfterMs > 0
			? opts.staleAfterMs
			: 60000;
	const minDisk =
		typeof opts.minDiskHeadroomMb === "number" && opts.minDiskHeadroomMb >= 0
			? opts.minDiskHeadroomMb
			: 100;

	if (record.status !== "active") return { ok: false, reason: "NOT_ACTIVE" };
	if (record.paused === true) return { ok: false, reason: "PAUSED" };
	const seen = Date.parse(record.lastSeenAt || "");
	if (!Number.isFinite(seen) || now - seen > staleAfterMs) {
		return { ok: false, reason: "STALE_HEARTBEAT" };
	}
	const caps = record.capabilities || {};
	if (caps.runnable === false) return { ok: false, reason: "NOT_RUNNABLE" };
	const protocol =
		caps.versions?.protocol || record.facts?.versions?.protocol;
	if (protocol !== RUNNER_PROTOCOL) {
		return { ok: false, reason: "PROTOCOL_SKEW" };
	}
	const runnerApi = caps.versions?.api || record.facts?.versions?.api;
	if (!runnerApiCompatible(runnerApi).ok) {
		return { ok: false, reason: "PROTOCOL_SKEW" };
	}
	// Only the raw string marker (taskRequirements' `{ alias: name }`) is
	// unservable here. A resolved alias object (`{ name, targetIndex }`,
	// stamped by the route after central D3 resolution) carries the
	// concrete harness/model below and matches like any direct requirement.
	if (typeof req.alias === "string" && req.alias) {
		return { ok: false, reason: "ALIAS_UNRESOLVED" };
	}
	if (req.harness) {
		const offered = Array.isArray(caps.harnesses) ? caps.harnesses : [];
		if (!offered.some((h) => h && h.id === req.harness)) {
			return { ok: false, reason: "NO_HARNESS" };
		}
	}
	if (req.model) {
		const models = Array.isArray(caps.models) ? caps.models : [];
		if (!models.includes(req.model)) return { ok: false, reason: "NO_MODEL" };
	}
	if (req.tier) {
		const tiers = Array.isArray(caps.tiers) ? caps.tiers : [];
		if (!tiers.includes(req.tier)) return { ok: false, reason: "TIER_CEILING" };
	}
	if (caps.diskHeadroomMb !== null && caps.diskHeadroomMb !== undefined) {
		if (caps.diskHeadroomMb < minDisk) return { ok: false, reason: "DISK_LOW" };
	}
	return { ok: true, reason: "MATCH" };
}

import { ALIAS_HARNESS_ID } from "../../../shared/modelAliases.js";
import { resolveHarnessName } from "../../agent/harnessRegistry.js";

/***
 * MARK: taskRequirements
 * @description Derives what a task's current stage needs from a Runner:
 *   harness (stage override else project default else configured default,
 *   same order as the embedded `resolveHarnessName`),
 *   model (stage else project default), and required tier (explicit
 *   stage/task tier else T1 for model-driven stages else T0). Stages whose
 *   harness is the `alias` virtual id resolved by the dispatch route in
 *   WP-3.2 (D3 central counters via `resolveAliasRequirement`, sharing the
 *   embedded smooth-WRR rotation) and are marked `{ alias }` so
 *   unresolvable aliases miss loudly instead of guessing. Only
 *   agent/review stages are Runner-runnable;
 *   human, command, and ci stages stay embedded.
 * @example taskRequirements({ harness: 'pi' }, { currentStageId: 's1', stages: [{ id: 's1', type: 'agent' }] }) => { harness: 'pi', ... }
 * @param {Object} project - Project entity.
 * @param {Object} task - Task entity.
 * @returns {Object} `{ harness, model, tier, alias, runnableType }`.
 ***/
export function taskRequirements(project = {}, task = {}) {
	const stages = Array.isArray(task.stages)
		? task.stages
		: Array.isArray(project?.stages)
			? project.stages
			: [];
	const stage =
		stages.find((s) => String(s?.id) === String(task.currentStageId)) ||
		stages[0] ||
		{};
	const type = String(stage.type || "agent").toLowerCase();
	const kind = type === "ci" || type === "script" || type === "deploy" || type === "command" ? "ci" : type === "merge" ? "merge" : type;
	// Retired (was DA9): every command stage is Runner-runnable — the
	// backend never executes stage commands. `hostCommand` stays in the
	// returned shape (always false) so existing consumers keep working.
	const hostCommand = false;
	// Merge stages are Runner-runnable as leased `integrate` jobs (Step 4):
	// the dispatch route matches them like CI (no harness/model, T0) and
	// the integration lease — not a harness — is the fencing token.
	const runnableType = type === "agent" || type === "review" || kind === "ci" || kind === "merge";

	// Same order as the embedded run path (`resolveHarnessName`): stage
	// override → project default → configured default → built-in. Dispatch
	// must demand exactly what the engine would run, or every default-harness
	// host misses every task (NO_HARNESS) while embedded runs them fine.
	const rawHarness = resolveHarnessName(project, { harnessName: stage.harness });

	let alias = null;
	let harness = rawHarness;
	if (rawHarness === ALIAS_HARNESS_ID) {
		const name =
			typeof stage.model === "string" && stage.model.trim()
				? stage.model.trim()
				: typeof project?.defaultModel === "string" && project.defaultModel.trim()
					? project.defaultModel.trim()
					: "";
		alias = name || "(blank)";
		harness = null;
	}

	const model =
		typeof stage.model === "string" && stage.model.trim() && rawHarness !== ALIAS_HARNESS_ID
			? stage.model.trim()
			: typeof project?.defaultModel === "string" && project.defaultModel.trim()
				? project.defaultModel.trim()
				: "";

	const explicitTier = [stage.tier, task.tier, task.requiredTier].find((t) =>
		/^T[0-3]$/.test(String(t || "").trim()),
	);
	const tier = explicitTier
		? String(explicitTier).trim()
		: kind === "ci"
			? "T0"
			: runnableType
				? "T1"
				: "T0";

	const runnerless = kind === "ci" || kind === "merge";
	return { harness: runnerless ? null : harness, model: runnerless ? "" : model, tier: runnerless && !explicitTier ? "T0" : tier, alias: runnerless ? null : alias, runnableType, hostCommand, kind, stageId: stage.id ?? null };
}

import { config } from "../config.js";
import { applyRunnerReport } from "./execution/applyRunnerReport.js";
import { applyIntegrationReport } from "./execution/applyIntegrationReport.js";
import { normalizeStageType } from "../projectStore.js";
import { git, defaultBranch } from "../git.js";
import { circuitSnapshot, isTripped } from "./circuitBreaker.js";
import { scanClaimableTasks } from "./dispatch/scanClaimableTasks.js";
import { resolveAliasRequirement } from "./dispatch/resolveAliasRequirement.js";
import { runnerMatches } from "./dispatch/runnerMatches.js";
import { curateRunnerPrompt } from "./curateRunnerPrompt.js";
import { materializeRunnerTaskDocs } from "./execution/materializeRunnerTaskDocs.js";
import { buildCommandKeywordContext, expandStageCommand } from "./commandStages.js";
import { resolveStagesForTask } from "./stageResolution.js";
import { emitStageLifecycle } from "./stageLifecycle.js";
import {
	resolveStageTimeout,
	runnerStageTimeoutStatus,
} from "./stagePolicy.js";

/***
 * MARK: resolveCiTimeoutMs
 * @description CI budget for one dispatched stage, in milliseconds. Honors
 *   the stage's explicit `timeoutMs`, then the legacy `timeout` field the
 *   project file actually carries, then the project default, then the
 *   10-minute floor. The `timeout` fallback matters: without it the
 *   Automated-tests stage's configured 3600000ms never reached the runner
 *   and every gate longer than 10 minutes was SIGKILLed mid-run (task
 *   b5716327: green suites reported as "exit code 1").
 * @example resolveCiTimeoutMs({ timeout: 3600000 }, {}) => 3600000
 * @param {Object} [resolved] - resolved CI stage definition.
 * @param {Object} [project] - project record (optional `ciTimeoutMs`).
 * @returns {number} Effective CI timeout in milliseconds.
 ***/
export const resolveCiTimeoutMs = (resolved, project) => {
	return (
		Number(resolved?.timeoutMs) ||
		Number(resolved?.timeout) ||
		Number(project?.ciTimeoutMs) ||
		600000
	);
};

/***
 * MARK: prepareIntegrationAttempt
 * @description Backend-side preparation for one leased `integrate` dispatch
 *   (Step 4): fetches the origin (read-only — the backend never pushes),
 *   reads the remote task-branch and target-branch tips as the attempt's
 *   expected SHAs, and pins a stable `mergeAttemptId` on the task so every
 *   dispatch poll for this merge reuses one queue entry (idempotent
 *   re-enqueue) instead of queueing a duplicate merge per poll. Throws
 *   `INTEGRATION_UNPREPARED` when the refs cannot be read (no origin ref
 *   yet, fetch failure) — the task stays `in_stage` for the next poll.
 * @example await prepareIntegrationAttempt({ taskStore, projectStore, projectId: 'p', task }) => { targetBranch: 'main', ... }
 * @param {Object} args - `{ taskStore, projectStore, projectId, task }`.
 * @returns {Promise<Object>} `{ targetBranch, taskBranch, expectedTaskSha, expectedTargetSha, mergeAttemptId }`.
 ***/
export const prepareIntegrationAttempt = async ({ taskStore, projectStore, projectId, task }) => {
	const unprepared = (detail) => {
		const err = new Error(`Integration attempt unprepared: ${detail}`);
		err.code = "INTEGRATION_UNPREPARED";
		throw err;
	};
	const project = projectStore?.getProject?.(projectId);
	const cwd = project?.cwd;
	if (!cwd) unprepared("project has no checkout");
	const taskBranch = taskStore.resolveTaskBranch(task);
	let targetBranch;
	try {
		targetBranch = await defaultBranch(cwd);
	} catch {
		unprepared("cannot resolve the target branch");
	}
	try {
		// Prune: a deleted remote task branch must vanish from the
		// remote-tracking refs too, or a later attempt would merge a
		// resurrected stale tip.
		await git(cwd, ["fetch", "--prune", "origin"], { timeout: 60000 });
	} catch (e) {
		unprepared(`fetch failed (${e?.message || e})`);
	}
	const readRef = async (ref) => {
		try {
			return (await git(cwd, ["rev-parse", "--verify", ref])).stdout.trim() || null;
		} catch {
			return null;
		}
	};
	const expectedTargetSha = await readRef(`origin/${targetBranch}`);
	const expectedTaskSha = await readRef(`origin/${taskBranch}`);
	if (!expectedTargetSha) unprepared(`remote ref 'origin/${targetBranch}' does not exist`);
	if (!expectedTaskSha) unprepared(`remote ref 'origin/${taskBranch}' does not exist (task work not pushed yet)`);
	// A retry after a failed attempt gets a FRESH attempt id: the failed
	// lease settled terminal (landed/conflict/stale-head/failed) in the
	// integration queue, and re-enqueueing the same id would collide with
	// that settled entry instead of queueing a re-based merge.
	const failedBefore = !!(task.lastError && (task.lastError.message || task.lastError.reason || task.lastError.stageId || task.lastError.stderr));
	let mergeAttemptId = `merge-${String(task.id).slice(0, 8)}-${Date.now()}`;
	if (typeof task.mergeAttemptId === "string" && task.mergeAttemptId.trim() && !failedBefore) {
		mergeAttemptId = task.mergeAttemptId.trim();
	} else {
		taskStore.updateTask(projectId, task.id, { mergeAttemptId }, cwd);
		task.mergeAttemptId = mergeAttemptId;
	}
	return { targetBranch, taskBranch, expectedTaskSha, expectedTargetSha, mergeAttemptId };
};

/***
 * MARK: registerRunnerRoutes
 * @description Runner-facing endpoints (ADR 0009 lifecycle steps 1–6): join
 *   registration, heartbeat, the operator approve/deny/revoke/pause/resume
 *   + list surface the Phase 2 onboarding UI drives, the atomic task-claim
 *   route backed by ClaimStore (200 + lease or 409 + holder), and the
 *   execution-report endpoints (progress, logs, complete-execution with
 *   engine-owned finish, interrupt, monitor). Credential
 *   scope is enforced per request: the claim's Runner always comes from
 *   the authenticated credential, never from the body (R04 wrong-scope).
 * @example await app.register(runnerRoutes, { deps })
 ***/
export const registerRunnerRoutes = async (app, { deps }) => {
	const {
		runnerRegistry,
		claimStore,
		steerStore,
		executionLedger,
		integrationQueue,
		taskStore,
		projectStore,
		resolveAndGuardProject,
		eventBridge,
	} = deps;

	const sendStoreError = (reply, err) => {
		const status = err.statusCode || 500;
		const body = { error: err.message || "Internal error" };
		if (err.code) body.code = err.code;
		if (err.holder) body.holder = err.holder;
		return reply.status(status).send(body);
	};

	const ciPayloadFor = async (projectId, task, stage) => {
		if (!stage) return {};
		const project = projectStore.getProject(projectId);
		const stages = resolveStagesForTask(project, task);
		const resolved = stage || stages.find((x) => String(x?.id) === String(task?.currentStageId)) || stages[0];
		if (!resolved) return {};
		const type = String(resolved.type || "").toLowerCase();
		if (!["ci", "script", "deploy", "command"].includes(type)) return {};
		// Generic lifecycle seam (mirrors runCommandStage): every command
		// stage announces entry the same way, whether a Runner or the
		// backend executes it. Installed continuity plugins may record
		// entry markers and contribute child-process environment here;
		// with no plugins this is an empty bag. Never throws: a plugin
		// failure must not break dispatch.
		let lifecycleEnv = {};
		try {
			const lifecycle = await emitStageLifecycle("stage:enter", {
				store: taskStore,
				projectId,
				taskId: task?.id,
				stage: resolved,
				kind: "ci",
				cwd: project?.cwd || "",
			});
			if (lifecycle && typeof lifecycle.env === "object") {
				lifecycleEnv = lifecycle.env;
			}
		} catch {
			lifecycleEnv = {};
		}
		try {
			const ctx = buildCommandKeywordContext({ task, stage: resolved, project, projectCwd: project?.cwd || "" });
			return {
				kind: "ci",
				command: expandStageCommand(resolved.command || resolved.script || "echo 'CI stage completed'", ctx),
				timeoutMs: resolveCiTimeoutMs(resolved, project),
				runOnBranch: typeof resolved.runOnBranch === "string" ? resolved.runOnBranch : "task",
				env: lifecycleEnv,
			};
		} catch { return { kind: "ci", command: resolved.command || resolved.script || "", timeoutMs: 600000, env: lifecycleEnv }; }
	};

	const authedRunner = (request) => {
		const credential = String(
			request.headers?.["x-runner-credential"] || "",
		).trim();
		return runnerRegistry.authenticate(credential);
	};

	app.post("/runners/register", async (request, reply) => {
		try {
			const result = runnerRegistry.register({
				runnerId: request.body?.runnerId,
				joinToken: request.body?.joinToken,
				facts: request.body?.facts || {},
			});
			return reply.status(result.status === "pending" ? 202 : 200).send(result);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/heartbeat", async (request, reply) => {
		try {
			const runner = authedRunner(request);
			const result = runnerRegistry.heartbeat({
				runnerId: request.body?.runnerId || runner.runnerId,
				credential: String(
					request.headers?.["x-runner-credential"] || "",
				).trim(),
				facts: request.body?.facts || {},
				// G11 audit alert: one identity from multiple origins.
				origin: request.ip || null,
			});
			// D5 pull channel (ADR 0011): pending steers for this
			// Runner's live executions ride the heartbeat response, so
			// steering needs no second channel. Stale Runner, live
			// lease: the steer waits here until the TTL lapses.
			const pendingSteers = [];
			for (const hold of claimStore.liveHolds()) {
				if (hold.runnerId !== runner.runnerId) continue;
				for (const steer of steerStore.pendingFor(hold.executionId)) {
					pendingSteers.push({
						steerId: steer.steerId,
						taskId: hold.taskId,
						projectId: hold.projectId,
						executionId: hold.executionId,
						epoch: hold.epoch,
						text: steer.text,
					});
				}
			}
			return { ...result, pendingSteers };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/runners", async () => {
		return runnerRegistry.list();
	});

	app.post("/runners/:id/approve", async (request, reply) => {
		try {
			return runnerRegistry.approve(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/rotate", async (request, reply) => {
		try {
			return runnerRegistry.rotate(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/deny", async (request, reply) => {
		try {
			return runnerRegistry.deny(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/revoke", async (request, reply) => {
		try {
			return runnerRegistry.revoke(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/pause", async (request, reply) => {
		try {
			return runnerRegistry.pause(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/resume", async (request, reply) => {
		try {
			return runnerRegistry.resume(request.params.id);
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/:id/skip", async (request, reply) => {
		// Operator skip: advance the task this Runner currently holds past
		// its stage and release the lease, so the in-flight Runner report
		// lands stale (stage-moved) instead of re-advancing. Same operator
		// surface as pause/resume — no Runner credential needed. 404 when
		// the Runner is unknown or holds nothing; 409 when its task is
		// already on the last stage.
		try {
			const runnerId = request.params.id;
			const record = runnerRegistry
				.records()
				.find((r) => r && r.runnerId === runnerId);
			if (!record) {
				return reply
					.status(404)
					.send({ error: `Unknown Runner ${runnerId}.`, code: "UNKNOWN_RUNNER" });
			}
			const hold = claimStore
				.liveHolds()
				.find((h) => h && h.runnerId === runnerId);
			if (!hold) {
				return reply.status(404).send({
					error: `Runner ${runnerId} has no active task to skip.`,
					code: "NOTHING_TO_SKIP",
				});
			}
			const project = projectStore.getProject(hold.projectId);
			const task = taskStore.getTask(hold.projectId, hold.taskId);
			if (!task) {
				claimStore.invalidate(hold.taskId);
				return reply.status(404).send({
					error: "Held task not found.",
					code: "NOTHING_TO_SKIP",
				});
			}
			const stages = Array.isArray(project?.stages) ? project.stages : [];
			const index = stages.findIndex((s) => s && s.id === task.currentStageId);
			if (index === -1 || index >= stages.length - 1) {
				return reply.status(409).send({
					error: `Task ${hold.taskId} is already on the last stage.`,
					code: "NOTHING_TO_SKIP",
				});
			}
			const next = stages[index + 1];
			taskStore.updateTask(
				hold.projectId,
				hold.taskId,
				{ currentStageId: next.id },
				project?.cwd,
			);
			claimStore.invalidate(hold.taskId);
			return {
				success: true,
				runnerId,
				taskId: hold.taskId,
				from: task.currentStageId,
				to: next.id,
			};
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	const guardedTask = (request, reply) => {
		const projectId = resolveAndGuardProject(
			request.body?.projectId || request.query?.projectId,
			reply,
		);
		if (!projectId) return null;
		const task = taskStore.getTask(projectId, request.params.id);
		if (!task) {
			reply.status(404).send({ error: "Task not found" });
			return null;
		}
		return { projectId, task };
	};

	app.get("/runners/monitor", async () => {
		// Multi-Runner UI (WP-3.4): who runs what right now, so
		// Settings › Harness › Runners can show live assignments.
		// `scheduler` exposes the cutover deferral counters so a task
		// sitting in_stage is diagnosable: a climbing `deferredDispatch`
		// with no Runner pickup means the fleet is empty or mismatched.
		const liveAssignments = claimStore.liveHolds().map((hold) => {
			const record = runnerRegistry.records().find((r) => r.runnerId === hold.runnerId) || null;
			return {
				runnerId: hold.runnerId,
				projectId: hold.projectId,
				taskId: hold.taskId,
				executionId: hold.executionId,
				epoch: hold.epoch,
				startedAt: hold.startedAt ?? null,
				stageId: executionLedger.stageFor(hold.executionId),
				prompt: executionLedger.promptFor(hold.executionId),
				serving: executionLedger.servingFor(hold.executionId),
				lastSeenAt: record?.lastSeenAt ?? null,
			};
		});
		const sched = taskStore.schedulerStats || {};
		const scheduler = {
			ticks: sched.ticks || 0,
			dispatched: sched.dispatched || 0,
			deferredDispatch: sched.deferredDispatch || 0,
			deferredTripped: sched.deferredTripped || 0,
			lastOutcome: sched.lastOutcome ?? null,
			lastDispatchAt: sched.lastDispatchAt ?? null,
		};
		// Step 6: surface integration-queue health (depth/lease per scope
		// via GET /runners/integration; global lease counters here) so a
		// stuck merge queue is visible before tasks pile up behind it.
		const integration = integrationQueue ? integrationQueue.snapshot() : {};
		return { ...executionLedger.snapshot(), liveAssignments, scheduler, integration };
	});

	app.post("/tasks/:id/progress", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.recordProgress({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				stageId: request.body?.stageId,
				event: request.body?.event,
				prompt: request.body?.prompt ?? null,
				harness: request.body?.harness ?? null,
				model: request.body?.model ?? null,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/logs", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const receipt = executionLedger.ingestLogs({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				seq: request.body?.seq,
				bytes: request.body?.bytes,
			});
			// Live turn-by-turn stream: fan the ingested frame out over the
			// socket so the Logs tab shows Runner output as it happens, not
			// only after the next task refetch. Fire-and-forget: a dead
			// socket must never fail the ingest. Duplicates are suppressed
			// once the stored entry arrives (client dedupes on
			// executionId+seq), and duplicate/old frames are never emitted.
			if (!receipt.duplicate) {
				eventBridge
					?.emitProcessEvent(ctx.projectId, "process:stdout", {
						taskId: request.params.id,
						projectId: ctx.projectId,
						chunk: `[runner ${runner.runnerId}] ${request.body?.bytes ?? ""}`,
						tag: "[RUNNER]",
						runnerId: runner.runnerId,
						executionId: request.body?.executionId,
						seq: request.body?.seq,
					})
					?.catch?.(() => {});
			}
			return receipt;
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/verify-sha", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.noteRemoteVerification({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				sha: request.body?.sha ?? null,
				present: request.body?.present,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/complete-execution", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const receipt = await executionLedger.completeExecution({
				claimStore,
				taskStore,
				projectStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				sha: request.body?.sha ?? null,
				branch: request.body?.branch ?? null,
				posture: request.body?.posture ?? null,
			});
			if (receipt.duplicate) return receipt;
			// Engine-owned finish: the lease fence accepted the report, so
			// the backend now applies the same transitions as the embedded
			// path (report, survey park, failure routing, advance). The
			// task must still be live and on the reported stage; anything
			// else keeps the accepted report but skips the finish.
			const live = taskStore.getTask(ctx.projectId, request.params.id);
			const terminal = ["complete", "failed"].includes(
				String(live?.status).toLowerCase(),
			);
			if (terminal) {
				return { ...receipt, advanced: false, reason: "task-terminal" };
			}
			const runStage = receipt.reportedStage ?? live?.currentStageId ?? null;
			if (runStage && live?.currentStageId && runStage !== live.currentStageId) {
				return { ...receipt, advanced: false, reason: "stage-moved" };
			}
			const outcome = request.body?.outcome ?? "passed";
			if (outcome !== "passed" && outcome !== "failed") {
				return reply.status(400).send({
					error: "outcome must be passed or failed",
					code: "INVALID_OUTCOME",
				});
			}
			// Runner-authored task files (plan/survey) land in the backend
			// task folder BEFORE the finish advances the task, so a following
			// backend-run CI stage reading {{taskDocs}} can see them.
			materializeRunnerTaskDocs({
				project: projectStore.getProject(ctx.projectId),
				taskId: request.params.id,
				files: request.body?.taskFiles,
			});
			const harnessId =
				runner.facts?.harnesses?.[0]?.id || request.body?.harnessId || "unknown";
			// Runner-run integration: the merge already landed via the
			// leased CAS push — verify read-only, freeze the baseline,
			// and advance. Never the generic stage finish.
			const project = projectStore.getProject(ctx.projectId);
			const allStages = resolveStagesForTask(project, live);
			const currentStage =
				allStages.find((s) => String(s?.id) === String(live?.currentStageId)) || allStages[0] || {};
			if (
				normalizeStageType(currentStage.type) === "merge" &&
				request.body?.integration?.outcome === "landed"
			) {
				const finish = await applyIntegrationReport({
					store: taskStore,
					projectStore,
					projectId: ctx.projectId,
					taskId: request.params.id,
					stage: currentStage,
					stages: allStages,
					integration: request.body.integration,
					runnerId: runner.runnerId,
				});
				return { ...receipt, ...finish };
			}
			const finish = await applyRunnerReport({
				store: taskStore,
				projectStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				outcome: {
					status: outcome,
					output: request.body?.output ?? "",
					summary: request.body?.summary ?? "",
					modifiedFiles: request.body?.modifiedFiles ?? [],
					harnessId,
					failureKind: request.body?.failureKind ?? null,
					failureReason: request.body?.failureReason ?? null,
					duration: request.body?.durationMs
						? String(Number(request.body.durationMs) / 1000)
						: "0.0",
					runnerId: runner.runnerId,
				},
			});
			return { ...receipt, ...finish };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/interrupt", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			return executionLedger.interruptExecution({
				claimStore,
				taskStore,
				projectId: ctx.projectId,
				taskId: request.params.id,
				runnerId: runner.runnerId,
				executionId: request.body?.executionId ?? null,
				reason: request.body?.reason ?? null,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/claim", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const claimedRunnerId = request.body?.runnerId;
		if (
			claimedRunnerId &&
			claimedRunnerId !== runner.runnerId
		) {
			return reply.status(403).send({
				error: "Credential does not belong to the claimed Runner.",
				code: "SCOPE_MISMATCH",
			});
		}
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		const projectId = resolveAndGuardProject(
			request.body?.projectId || request.query?.projectId,
			reply,
		);
		if (!projectId) return;
		const task = taskStore.getTask(projectId, request.params.id);
		if (!task) return reply.status(404).send({ error: "Task not found" });
		try {
			const { executionId, epoch } = claimStore.claim(
				request.params.id,
				runner.runnerId,
				projectId,
			);
			return { taskId: request.params.id, runnerId: runner.runnerId, executionId, epoch, ...await ciPayloadFor(projectId, task, null), prompt: curateRunnerPrompt({ project: projectStore.getProject(projectId), task, stageId: task.currentStageId }) };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/tasks/:id/claim-heartbeat", async (request, reply) => {
		// Lease renewal for long Runner executions (D1): the claim TTL
		// bounds a dead Runner's hold, so a live Runner must extend it
		// while the harness runs — otherwise the hold lapses mid-stage,
		// the task re-queues, and the finisher reports STALE_EPOCH.
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const hold = claimStore.describe(request.params.id);
			if (!hold || hold.runnerId !== runner.runnerId) {
				const err = new Error(
					`Stale execution for task ${request.params.id}: lease belongs to another Runner.`,
				);
				err.statusCode = 409;
				err.code = "STALE_EPOCH";
				throw err;
			}
			// Wall-clock stage timeout (no infinite renewal): a live Runner
			// renewing its lease forever must not outrun the stage budget —
			// otherwise a stuck harness sits claimed indefinitely and the
			// task reads frozen. On breach the hold is released and the
			// stage fails through the normal failure routing (retry/failback),
			// so the task re-queues instead of stranding.
			const project = projectStore.getProject(ctx.projectId);
			const stages = resolveStagesForTask(project, ctx.task);
			const stage =
				stages.find(
					(s) => String(s?.id) === String(ctx.task?.currentStageId),
				) || null;
			const timeoutMs = resolveStageTimeout(
				stage,
				stage?.type,
				config,
				project,
			);
			const { timedOut, elapsedMs } = runnerStageTimeoutStatus({
				startedAt: hold.startedAt ?? null,
				timeoutMs,
			});
			if (timedOut) {
				claimStore.invalidate(request.params.id);
				const reason =
					`Stage timed out after ${elapsedMs}ms (budget ${timeoutMs}ms) ` +
					`on stage '${stage?.name || stage?.id || ctx.task?.currentStageId}'.`;
				try {
					await applyRunnerReport({
						store: taskStore,
						projectStore,
						projectId: ctx.projectId,
						taskId: request.params.id,
						outcome: {
							status: "failed",
							output: "",
							harnessId: runner.facts?.harnesses?.[0]?.id || "unknown",
							failureKind: "timeout",
							failureReason: reason,
							duration: String(elapsedMs / 1000),
							runnerId: runner.runnerId,
						},
					});
				} catch {
					// The 409 below is the contract; a reporting failure must
					// never mask it (the zombie's late finish stays stale).
				}
				return reply.status(409).send({
					error: reason,
					code: "STAGE_TIMEOUT",
					timeoutMs,
					elapsedMs,
				});
			}
			const { epoch } = claimStore.heartbeat(
				request.params.id,
				request.body?.executionId,
			);
			return { taskId: request.params.id, runnerId: runner.runnerId, epoch };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/dispatch", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!runnerRegistry.isFresh(runner)) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is stale — heartbeat, then ask again`,
				code: "STALE_RUNNER",
			});
		}
		// Parked Runners keep heartbeating (freshness is liveness, not
		// eligibility) but take no new work: fail fast here as well as in
		// the per-candidate match, so a paused fleet reads as paused and
		// not "no capable match".
		if (runner.paused === true) {
			return reply.status(409).send({
				error: `Runner ${runner.runnerId} is paused — resume it to take new tasks`,
				code: "RUNNER_PAUSED",
			});
		}
		if (isTripped(taskStore)) {
			const circuit = circuitSnapshot(taskStore);
			return reply.status(409).send({
				error: "Engine is tripped — dispatch is stopped",
				tripped: true,
				reason: circuit.reason,
				source: circuit.source,
				trippedAt: circuit.trippedAt,
			});
		}
		const projectIds = Array.isArray(request.body?.projectIds)
			? request.body.projectIds
			: undefined;
		runnerRegistry.recordDispatchScope(runner.runnerId, projectIds);
		// D8 burn control (ADR 0010): the fleet cap stops parallel burn
		// before any scan; per-project caps skip that project's candidates
		// below. 0 disables that cap (default: single-Runner behaviour).
		const fleetCap = config.runnerMaxConcurrentFleet || 0;
		if (fleetCap > 0 && claimStore.countLiveHolds() >= fleetCap) {
			return reply.status(429).send({
				error: `Fleet at Runner concurrency cap (${fleetCap}); backing off.`,
				code: "FLEET_CONCURRENCY_EXHAUSTED",
			});
		}
		const projectCap = config.runnerMaxConcurrentPerProject || 0;
		const candidates = scanClaimableTasks(
			{ projectStore, taskStore, claimStore },
			{ projectIds, maxWaitMs: config.dispatchMaxWaitMs || 0 },
		);
		if (candidates.length === 0) {
			return { assigned: false, code: "NO_CLAIMABLE_TASKS" };
		}
		// A harness is dispatch-servable when some active, fresh Runner
		// advertises it. Alias targets on unserved harnesses are skipped
		// for this resolution (share redistributes, per the alias
		// contract); nothing served at all resolves null → loud miss.
		const isHarnessKnown = (name) =>
			runnerRegistry.records().some(
				(rec) =>
					rec?.status === "active" &&
					rec?.paused !== true &&
					runnerRegistry.isFresh(rec) &&
					(rec.capabilities?.harnesses || []).some((h) => h?.id === name),
			);
		const misses = {};
		for (const cand of candidates) {
			let req = cand.req;
			if (cand.req.alias) {
				const resolved = resolveAliasRequirement({
					project: projectStore.getProject(cand.projectId),
					aliasName: cand.req.alias,
					isHarnessKnown,
				});
				if (!resolved) {
					misses.ALIAS_UNRESOLVED = (misses.ALIAS_UNRESOLVED || 0) + 1;
					continue;
				}
				req = {
					...cand.req,
					harness: resolved.harness,
					model: resolved.model,
					alias: { name: resolved.aliasName, targetIndex: resolved.targetIndex },
				};
			}
			const verdict = runnerMatches(runner, req, {
				staleAfterMs: runnerRegistry.staleAfterMs,
			});
			if (!verdict.ok) {
				misses[verdict.reason] = (misses[verdict.reason] || 0) + 1;
				continue;
			}
			if (
				projectCap > 0 &&
				claimStore.countLiveHolds({ projectId: cand.projectId }) >= projectCap
			) {
				misses.PROJECT_BUSY = (misses.PROJECT_BUSY || 0) + 1;
				continue;
			}
			// Merge stages dispatch as leased `integrate` jobs (Step 4): the
			// task claim fences progress/logs/completion exactly like any
			// stage, while the integration lease serializes target-branch
			// writes. A busy integration slot backs the Runner off to poll
			// again (the request stays queued — never lost, never doubled).
			if (req.kind === "merge") {
				let attempt;
				try {
					attempt = await prepareIntegrationAttempt({
						taskStore,
						projectStore,
						projectId: cand.projectId,
						task: cand.task,
					});
				} catch (err) {
					if (err?.code === "INTEGRATION_UNPREPARED") {
						misses.INTEGRATION_UNPREPARED = (misses.INTEGRATION_UNPREPARED || 0) + 1;
						continue;
					}
					return sendStoreError(reply, err);
				}
				let executionId;
				let epoch;
				try {
					({ executionId, epoch } = claimStore.claim(cand.taskId, runner.runnerId, cand.projectId));
				} catch (err) {
					if (err?.code === "CLAIM_CONFLICT") continue;
					return sendStoreError(reply, err);
				}
				if (!integrationQueue) {
					claimStore.invalidate(cand.taskId);
					misses.NO_INTEGRATION_QUEUE = (misses.NO_INTEGRATION_QUEUE || 0) + 1;
					continue;
				}
				integrationQueue.enqueue({
					projectId: cand.projectId,
					targetBranch: attempt.targetBranch,
					taskId: cand.taskId,
					taskBranch: attempt.taskBranch,
					expectedTaskSha: attempt.expectedTaskSha,
					expectedTargetSha: attempt.expectedTargetSha,
					mergeAttemptId: attempt.mergeAttemptId,
				});
				let lease;
				try {
					lease = integrationQueue.acquire({
						projectId: cand.projectId,
						targetBranch: attempt.targetBranch,
						runnerId: runner.runnerId,
					});
				} catch (err) {
					claimStore.invalidate(cand.taskId);
					if (err?.code === "INTEGRATION_BUSY") {
						return { assigned: false, code: "INTEGRATION_BUSY" };
					}
					return sendStoreError(reply, err);
				}
				if (!lease.leased) {
					claimStore.invalidate(cand.taskId);
					misses.INTEGRATION_EMPTY = (misses.INTEGRATION_EMPTY || 0) + 1;
					continue;
				}
				return {
					assigned: true,
					projectId: cand.projectId,
					taskId: cand.taskId,
					runnerId: runner.runnerId,
					executionId,
					epoch,
					stageId: cand.stage?.id ?? null,
					kind: "integrate",
					integration: {
						taskBranch: attempt.taskBranch,
						expectedTaskSha: attempt.expectedTaskSha,
						targetBranch: attempt.targetBranch,
						expectedTargetSha: attempt.expectedTargetSha,
						mergeAttemptId: attempt.mergeAttemptId,
						integrationExecutionId: lease.executionId,
						integrationEpoch: lease.epoch,
					},
					requirements: req,
				};
			}
			try {
				const { executionId, epoch } = claimStore.claim(
					cand.taskId,
					runner.runnerId,
					cand.projectId,
				);
				return {
					assigned: true,
					projectId: cand.projectId,
					taskId: cand.taskId,
					runnerId: runner.runnerId,
					executionId,
					epoch,
					stageId: cand.stage?.id ?? null,
					prompt: curateRunnerPrompt({ project: projectStore.getProject(cand.projectId), task: cand.task, stageId: cand.stage?.id }),
					...await ciPayloadFor(cand.projectId, cand.task, cand.stage),
					requirements: req,
				};
			} catch (err) {
				if (err?.code === "CLAIM_CONFLICT") continue;
				return sendStoreError(reply, err);
			}
		}
		return { assigned: false, code: "NO_CAPABLE_MATCH", misses };
	});

	// ---- Integration leases (Step 3: serialized Runner-run merges) ---------
	// The backend never merges or pushes: it queues merge requests
	// (enqueue is backend-internal, called by the merge stage) and leases
	// the head entry to one Runner per project + target branch. The Runner
	// holds `executionId`/`epoch` exactly like a task claim; a superseded
	// report is stale by construction.
	app.post("/runners/integration/acquire", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		try {
			return integrationQueue.acquire({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				runnerId: runner.runnerId,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/integration/heartbeat", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		try {
			return integrationQueue.heartbeat({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.post("/runners/integration/report", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		if (!integrationQueue) {
			return reply.status(503).send({ error: "Integration queue unavailable.", code: "NO_INTEGRATION_QUEUE" });
		}
		try {
			const receipt = integrationQueue.report({
				projectId: request.body?.projectId,
				targetBranch: request.body?.targetBranch,
				executionId: request.body?.executionId,
				epoch: request.body?.epoch,
				outcome: request.body?.outcome,
				mergeSha: request.body?.mergeSha ?? null,
				detail: request.body?.detail ?? null,
			});
			return { ...receipt, runnerId: runner.runnerId };
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/runners/integration", async (request) => {
		if (!integrationQueue) return { depth: 0, lease: null, counters: {} };
		return {
			...integrationQueue.describe({
				projectId: request.query?.projectId,
				targetBranch: request.query?.targetBranch,
			}),
			counters: integrationQueue.snapshot(),
		};
	});

	// ---- Steering acks (D5, ADR 0011) --------------------------------------
	// The unified POST /tasks/:id/steer (taskFlowRoutes) queues against the
	// live lease; the Runner pulls on heartbeat and acks here.
	app.post("/tasks/:id/steer-ack", async (request, reply) => {
		let runner;
		try {
			runner = authedRunner(request);
		} catch (err) {
			return sendStoreError(reply, err);
		}
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		try {
			const hold = claimStore.describe(request.params.id);
			if (
				!hold ||
				hold.executionId !== request.body?.executionId ||
				hold.epoch !== request.body?.epoch ||
				hold.runnerId !== runner.runnerId
			) {
				return reply.status(409).send({
					error: `Ack targets a superseded execution (no matching live lease).`,
					code: "STALE_EPOCH",
				});
			}
			return steerStore.ack(request.body.executionId, request.body?.steerId, {
				ok: request.body?.ok,
				detail: request.body?.detail,
			});
		} catch (err) {
			return sendStoreError(reply, err);
		}
	});

	app.get("/tasks/:id/steers", async (request, reply) => {
		const ctx = guardedTask(request, reply);
		if (!ctx) return;
		const executionId = request.query?.executionId;
		if (!executionId || typeof executionId !== "string") {
			return reply.status(400).send({
				error: "steers requires an executionId query.",
				code: "INVALID_STEER_ARGS",
			});
		}
		return {
			taskId: request.params.id,
			executionId,
			pending: steerStore.pendingFor(executionId),
			receipts: steerStore.receiptsFor(executionId),
		};
	});
};

import { _appendProcessLog } from "../watch/index.js";
import { git } from "../git.js";

/***
 * MARK: ExecutionLedger
 * @description Backend receiving side of the Runner wire protocol (ADR 0009
 *   lifecycle steps 4–6): sequenced progress events, sequenced log frames,
 *   idempotent completion, and interruption. Every mutating call first
 *   checks the ClaimStore lease — a stale epoch is rejected before any
 *   state changes, which is what makes a partitioned zombie's late report
 *   a 409 instead of a double completion (R01). Dedupe is per execution:
 *   a retried report is a recorded no-op, never a duplicate stage (step 4).
 *   Log gaps are represented in the data ("frames missing — Runner
 *   disconnected"), never papered over (R14). Completion records the
 *   Runner's report (SHA/branch/posture) and releases the lease; stage
 *   advancement stays engine-owned until the dispatch integration lands.
 *   Monitor counters back the Phase 2 "pageable-zero" reconcile/divergence
 *   signals. In-memory for Phase 2 (same durability story as ClaimStore).
 * @example const ledger = new ExecutionLedger()
 * @param {Object} [opts] - Options.
 ***/
/***
 * MARK: ExecutionLedger
 * @description In-memory receiving side for Runner progress/logs/complete/
 *   interrupt keyed by lease. See the module block for the fencing contract.
 * @example const ledger = new ExecutionLedger(); ledger.snapshot() => { progressRecorded: 0, ... }
 ***/
/***
 * MARK: MAX_RUNNER_INTERRUPTS
 * @description Bound on consecutive Runner-death interrupts for one
 *   task+stage (G7): a Runner that keeps dying mid-stage re-queues as
 *   `interrupted` each time, but past this many in a row the interrupt
 *   escalates (history entry + `interruptEscalations` monitor counter +
 *   `escalated` reply flag) so the death loop gets operator attention
 *   instead of spinning forever. A successful completion resets the count.
 * @example MAX_RUNNER_INTERRUPTS => 5
 ***/
export const MAX_RUNNER_INTERRUPTS = 5;

/***
 * MARK: ExecutionLedger
 * @description In-memory receiving side for Runner progress/logs/complete/
 *   interrupt keyed by lease (D1 fencing, R01/R14); consecutive Runner-death
 *   interrupts escalate past MAX_RUNNER_INTERRUPTS (G7). See the module
 *   block above for the full fencing contract.
 * @example const ledger = new ExecutionLedger()
 * @example ledger.snapshot() => { progressRecorded: 0, … }
 ***/
export class ExecutionLedger {
	constructor() {
		this.seenProgress = new Set();
		this.logNextSeq = new Map();
		this.lastStage = new Map();
		this.stagePrompt = new Map();
		this.stageServing = new Map();
		this.counters = {
			progressRecorded: 0,
			progressDuplicates: 0,
			logFrames: 0,
			logGaps: 0,
			logDuplicates: 0,
			completions: 0,
			completionDuplicates: 0,
			staleRejected: 0,
			interrupts: 0,
			interruptEscalations: 0,
			divergences: 0,
			unverifiedSha: 0,
			verifiedSha: 0,
		};
	}

	static _stale(taskId, why) {
		const err = new Error(`Stale execution for task ${taskId}: ${why}.`);
		err.statusCode = 409;
		err.code = "STALE_EPOCH";
		return err;
	}

	_holdOrThrow(claimStore, taskId, executionId, epoch) {
		const hold = claimStore.describe(taskId);
		if (
			!hold ||
			hold.executionId !== executionId ||
			hold.epoch !== epoch
		) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "epoch or execution mismatch");
		}
		return hold;
	}

	recordProgress({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		stageId,
		event,
		prompt = null,
		harness = null,
		model = null,
	}) {
		const hold = this._holdOrThrow(claimStore, taskId, executionId, epoch);
		if (hold.runnerId !== runnerId) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "lease belongs to another Runner");
		}
		if (!stageId || !event) {
			const err = new Error("progress requires stageId and event.");
			err.statusCode = 400;
			err.code = "INVALID_PROGRESS_ARGS";
			throw err;
		}
		const key = `${executionId}|${stageId}|${event}`;
		if (this.seenProgress.has(key)) {
			this.counters.progressDuplicates += 1;
			return { recorded: true, duplicate: true };
		}
		this.seenProgress.add(key);
		this.lastStage.set(executionId, stageId);
		// Stage prompt payload (observability only): the exact prompt the
		// Runner curated for this execution, capped at ingest. Kept per
		// live execution and dropped on complete/interrupt with the rest
		// of the per-execution state.
		if (event === "prompted" && typeof prompt === "string" && prompt) {
			this.stagePrompt.set(executionId, prompt.slice(0, 20000));
		}
		// Serving harness/model (observability only): what the Runner
		// actually runs this execution on. Same lifecycle as the prompt.
		if (event === "prompted" && (harness || model)) {
			this.stageServing.set(executionId, {
				harness: typeof harness === "string" ? harness : null,
				model: typeof model === "string" ? model : null,
			});
		}
		this.counters.progressRecorded += 1;
		const task = taskStore.getTask(projectId, taskId);
		task?.history?.push({
			timestamp: new Date().toISOString(),
			action: `Runner ${runnerId} stage ${stageId}: ${event}`,
		});
		return { recorded: true, duplicate: false };
	}

	ingestLogs({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		seq,
		bytes,
	}) {
		this._holdOrThrow(claimStore, taskId, executionId, epoch);
		if (!Number.isInteger(seq) || seq < 0 || typeof bytes !== "string") {
			const err = new Error("logs requires an integer seq and string bytes.");
			err.statusCode = 400;
			err.code = "INVALID_LOG_ARGS";
			throw err;
		}
		const next = this.logNextSeq.get(executionId) ?? 0;
		if (seq < next) {
			this.counters.logDuplicates += 1;
			return { accepted: true, duplicate: true, seq };
		}
		const task = taskStore.getTask(projectId, taskId);
		if (seq > next) {
			this.counters.logGaps += 1;
			this.counters.logFrames += 1;
			_appendProcessLog(
				task,
				`[runner ${runnerId}] logs truncated — Runner disconnected (frames ${next}–${seq - 1} missing)`,
				{ runnerId },
			);
		} else {
			this.counters.logFrames += 1;
		}
		_appendProcessLog(task, `[runner ${runnerId}] ${bytes}`, {
			runnerId,
			executionId,
			seq,
		});
		this.logNextSeq.set(executionId, seq + 1);
		return { accepted: true, duplicate: false, seq };
	}

	async completeExecution({
		claimStore,
		taskStore,
		projectStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		sha = null,
		branch = null,
		posture = null,
	}) {
		let outcome;
		try {
			outcome = claimStore.complete(taskId, executionId, epoch);
		} catch (err) {
			this.counters.staleRejected += 1;
			throw err;
		}
		if (outcome.duplicate) {
			this.counters.completionDuplicates += 1;
			return { accepted: true, duplicate: true };
		}
		this.counters.completions += 1;
		const task = taskStore.getTask(projectId, taskId);
		const project = projectStore?.getProject?.(projectId);

		let shaState = "absent";
		if (sha && project?.cwd && !project?.hasUpstreamRepo) {
			try {
				// cat-file -e verifies the object exists; rev-parse alone
				// would echo back any 40-hex string without checking.
				await git(project.cwd, ["cat-file", "-e", `${sha}^{commit}`]);
				shaState = "present";
			} catch {
				shaState = "unverifiable";
				this.counters.unverifiedSha += 1;
			}
		} else if (sha) {
			shaState = "unverified-remote";
			this.counters.unverifiedSha += 1;
			// Deferred verification (Step 3): the backend cannot fetch the
			// remote (D2), so the reported SHA stays pending until a Runner
			// with a fresh fetch confirms it via noteRemoteVerification
			// (POST /tasks/:id/verify-sha). Visible per task, not just as a
			// monitor counter.
			if (task && branch) {
				task.pendingPushVerification = {
					sha,
					branch,
					verified: false,
					reportedAt: new Date().toISOString(),
					reportedBy: runnerId,
				};
			}
		}

		const reportedStage = this.lastStage.get(executionId) ?? null;
		const currentStage = task?.currentStageId ?? null;
		const terminal = ["complete", "failed"].includes(
			String(task?.status).toLowerCase(),
		);
		if ((reportedStage && currentStage && reportedStage !== currentStage) || terminal) {
			this.counters.divergences += 1;
			task?.history?.push({
				timestamp: new Date().toISOString(),
				action: `Reconciler: execution ${executionId} reported stage ${reportedStage ?? "?"} but task is at stage ${currentStage ?? "?"} (status ${task?.status}) — report kept, divergence counted.`,
			});
		}

		const postureBits = [
			runnerId && `runner ${runnerId}`,
			`epoch ${epoch}`,
			sha && `sha ${sha} (${shaState})`,
			branch && `branch ${branch}`,
			posture && `posture ${posture}`,
		]
			.filter(Boolean)
			.join(", ");
		task?.history?.push({
			timestamp: new Date().toISOString(),
			action: `Runner completed execution ${executionId} (${postureBits}). Lease released.`,
		});
		// G7: a finished stage breaks the death loop — the next stage (or
		// a later retry of this one after real progress) counts from zero.
		if (task) {
			delete task.runnerInterruptCount;
			delete task.runnerInterruptStage;
		}
		this.lastStage.delete(executionId);
		this.logNextSeq.delete(executionId);
		this.stagePrompt.delete(executionId);
		this.stageServing.delete(executionId);
		return { accepted: true, duplicate: false, shaState, reportedStage };
	}

	/***
	 * MARK: noteRemoteVerification
	 * @description Confirms (or refutes) a previously reported push SHA
	 *   against a Runner's fresh fetch of the remote (Step 3 deferred
	 *   verification). Fenced by the task-claim lease exactly like progress
	 *   and logs: a stale execution's confirmation is rejected, never
	 *   recorded. Sets `task.pendingPushVerification.verified` and counts
	 *   `verifiedSha`; a refuted SHA leaves `verified: false` with the
	 *   refuting Runner named, so the task visibly needs a re-push.
	 * @example ledger.noteRemoteVerification({ claimStore, taskStore, projectId: 'p', taskId: 't', runnerId: 'r', executionId: 'e', epoch: 1, sha: 'abc', present: true }) => { verified: true }
	 ***/
	noteRemoteVerification({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId,
		epoch,
		sha,
		present,
	}) {
		const hold = this._holdOrThrow(claimStore, taskId, executionId, epoch);
		if (hold.runnerId !== runnerId) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "lease belongs to another Runner");
		}
		if (!sha || typeof sha !== "string") {
			const err = new Error("verify-sha requires a sha.");
			err.statusCode = 400;
			err.code = "INVALID_VERIFY_ARGS";
			throw err;
		}
		const task = taskStore.getTask(projectId, taskId);
		const verified = present !== false;
		if (task) {
			task.pendingPushVerification = {
				...(task.pendingPushVerification || {}),
				sha,
				verified,
				verifiedAt: new Date().toISOString(),
				verifiedBy: runnerId,
			};
			task?.history?.push({
				timestamp: new Date().toISOString(),
				action: verified
					? `Runner ${runnerId} verified push SHA ${sha.slice(0, 7)} against the remote.`
					: `Runner ${runnerId} could NOT find push SHA ${sha.slice(0, 7)} on the remote — task needs a re-push.`,
			});
		}
		if (verified) this.counters.verifiedSha += 1;
		else this.counters.unverifiedSha += 1;
		return { verified };
	}

	interruptExecution({
		claimStore,
		taskStore,
		projectId,
		taskId,
		runnerId,
		executionId = null,
		reason = null,
	}) {
		const hold = claimStore.describe(taskId);
		if (
			hold &&
			executionId &&
			(executionId !== hold.executionId || runnerId !== hold.runnerId)
		) {
			this.counters.staleRejected += 1;
			throw ExecutionLedger._stale(taskId, "not the lease holder");
		}
		const task = taskStore.getTask(projectId, taskId);
		if (["complete", "failed"].includes(String(task?.status).toLowerCase())) {
			const err = new Error(`Task ${taskId} is already terminal.`);
			err.statusCode = 409;
			err.code = "NOTHING_TO_INTERRUPT";
			throw err;
		}
		claimStore.invalidate(taskId);
		this.counters.interrupts += 1;
		// G7: consecutive interrupts per task+stage. A stage change (or a
		// successful completion, which clears both fields) restarts the
		// count — only a Runner dying repeatedly on the SAME stage trips
		// the bound.
		const stageId = task?.currentStageId ?? null;
		const prevStage = task?.runnerInterruptStage ?? null;
		const prevCount = Number.isInteger(task?.runnerInterruptCount) ? task.runnerInterruptCount : 0;
		const interruptCount = prevStage === stageId ? prevCount + 1 : 1;
		const escalated = interruptCount >= MAX_RUNNER_INTERRUPTS;
		if (task) {
			task.runnerInterruptStage = stageId;
			task.runnerInterruptCount = interruptCount;
			task.status = "interrupted";
			const cleanReason =
				typeof reason === "string" && reason.trim() ? reason.trim().slice(0, 500) : "";
			task?.history?.push({
				timestamp: new Date().toISOString(),
				action: `Runner ${runnerId} interrupted execution ${executionId ?? hold?.executionId ?? "?"} — lease dropped, re-queues as interrupted.${cleanReason ? ` Reason: ${cleanReason}` : ""}`,
			});
			if (escalated) {
				this.counters.interruptEscalations += 1;
				task?.history?.push({
					timestamp: new Date().toISOString(),
					action: `Runner deaths escalated: ${interruptCount} consecutive interrupts on stage ${stageId ?? "?"} (bound ${MAX_RUNNER_INTERRUPTS}) — needs operator attention, auto re-queue continues.`,
				});
			}
		}
		for (const id of [hold?.executionId, executionId]) {
			if (id) {
				this.lastStage.delete(id);
				this.logNextSeq.delete(id);
				this.stagePrompt.delete(id);
				this.stageServing.delete(id);
			}
		}
		return { interrupted: true, interruptCount, escalated };
	}

	/***
	 * MARK: stageFor
	 * @description Current stage reported by a live execution (progress
	 *   `started`/`finished` events). Null when unknown or finished —
	 *   per-runner monitor widgets join this to the claim hold.
	 * @example ledger.stageFor('exec-1') => 'stage-a'
	 * @param {string} executionId - Lease execution id.
	 * @returns {string|null} Last reported stage id.
	 ***/
	stageFor(executionId) {
		return this.lastStage.get(executionId) ?? null;
	}

	/***
	 * MARK: promptFor
	 * @description Exact stage prompt a live execution reported at start
	 *   (`prompted` progress event). Null when unreported or finished —
	 *   per-runner monitor widgets render the with-prompt card from this.
	 * @example ledger.promptFor('exec-1') => '# Task\n...'
	 * @param {string} executionId - Lease execution id.
	 * @returns {string|null} Reported stage prompt.
	 ***/
	promptFor(executionId) {
		return this.stagePrompt.get(executionId) ?? null;
	}

	/***
	 * MARK: servingFor
	 * @description Serving harness/model a live execution reported at start
	 *   (`prompted` progress event). Null when unreported or finished —
	 *   per-runner monitor widgets show these pills instead of the fleet
	 *   advertised capabilities.
	 * @example ledger.servingFor('exec-1') => { harness: 'pi', model: 'x' }
	 * @param {string} executionId - Lease execution id.
	 * @returns {Object|null} Serving `{ harness, model }`.
	 ***/
	servingFor(executionId) {
		return this.stageServing.get(executionId) ?? null;
	}

	snapshot() {
		return { ...this.counters };
	}
}

